values ('t10', 10, 'Mock Test #10', 7, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":2,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some sentences. Choose the correct reply to each sentence.","emphasis":"A, B or C","durationSec":53,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Not at all, go ahead."},{"key":"B","text":"Yes, I opened it."},{"key":"C","text":"It's on the left."}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Since next year."},{"key":"B","text":"For about three years."},{"key":"C","text":"In a language school."}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Don't worry, I've got another copy."},{"key":"B","text":"Yes, it's a great book."},{"key":"C","text":"I'll lend it to you."}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"","options":[{"key":"A","text":"It took an hour."},{"key":"B","text":"I didn't see any."},{"key":"C","text":"Let's walk, it isn't far."}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Good luck next time."},{"key":"B","text":"Thanks, I can't believe it!"},{"key":"C","text":"I'd rather drive."}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"","options":[{"key":"A","text":"It's next to the bank on Park Street."},{"key":"B","text":"I usually go there on Mondays."},{"key":"C","text":"Yes, I could."}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"","options":[{"key":"A","text":"What a great idea!"},{"key":"B","text":"Oh no, I was really looking forward to it."},{"key":"C","text":"I'll bring an umbrella then."}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I'd love to, thanks."},{"key":"B","text":"No, I had dinner."},{"key":"C","text":"It's on Friday."}]}],"audio":"t10/l1.mp3","audioAt":{"1":8,"2":12,"3":16,"4":21,"5":27,"6":32,"7":38,"8":44}},{"id":"l2","index":2,"title":"City Sports Centre — information for new members","instruction":"You will hear a guide talking to new members. Fill in the missing information. Write","emphasis":"ONE WORD and / or A NUMBER","durationSec":85,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Show your membership card at the"},{"id":"l-10","number":10,"kind":"gap","prompt":"On weekdays the pool closes at … pm"},{"id":"l-11","number":11,"kind":"gap","prompt":"Locker deposit: £"},{"id":"l-12","number":12,"kind":"gap","prompt":"Beginners’ yoga class: every"},{"id":"l-13","number":13,"kind":"gap","prompt":"In the gym, always use your own"},{"id":"l-14","number":14,"kind":"gap","prompt":"Members get … per cent off in the café"}],"audio":"t10/l2.mp3","audioAt":{"9":21,"10":31,"11":41,"12":49,"13":60,"14":68}},{"id":"l3","index":3,"instruction":"You will hear people speaking in different situations. Match each speaker (15–18) to the place where the speaker is (A–F). There are","emphasis":"TWO EXTRA places","durationSec":73,"choices":[{"key":"A","text":"at a railway station"},{"key":"B","text":"in a hospital"},{"key":"C","text":"at a hotel reception"},{"key":"D","text":"in a museum"},{"key":"E","text":"at a football match"},{"key":"F","text":"in a supermarket"}],"questions":[{"id":"l-15","number":15,"kind":"match","prompt":"Speaker 1"},{"id":"l-16","number":16,"kind":"match","prompt":"Speaker 2"},{"id":"l-17","number":17,"kind":"match","prompt":"Speaker 3"},{"id":"l-18","number":18,"kind":"match","prompt":"Speaker 4"}],"audio":"t10/l3.mp3","audioAt":{"15":14,"16":29,"17":43,"18":57}},{"id":"l4","index":4,"instruction":"You will hear someone giving a talk. Label the places (19–23) on the map (A–H). There are","emphasis":"THREE extra options","durationSec":91,"choices":[{"key":"A","text":""},{"key":"B","text":""},{"key":"C","text":""},{"key":"D","text":""},{"key":"E","text":""},{"key":"F","text":""},{"key":"G","text":""},{"key":"H","text":""}],"map":{"width":320,"height":240,"roads":[{"points":[[10,120],[310,120]]},{"points":[[160,10],[160,120]]},{"points":[[240,120],[240,230]]}],"blocks":[{"x":20,"y":72,"w":52,"h":34,"letter":"A"},{"x":92,"y":72,"w":52,"h":34,"letter":"B"},{"x":176,"y":36,"w":52,"h":34,"letter":"C"},{"x":250,"y":72,"w":52,"h":34,"letter":"D"},{"x":20,"y":134,"w":52,"h":34,"letter":"E"},{"x":92,"y":134,"w":52,"h":34,"letter":"F"},{"x":166,"y":134,"w":60,"h":34,"name":"Town hall"},{"x":256,"y":176,"w":52,"h":34,"letter":"G"},{"x":170,"y":186,"w":52,"h":34,"letter":"H"}],"labels":[{"x":60,"y":124,"text":"Main Street"},{"x":160,"y":20,"text":"North Road"},{"x":240,"y":236,"text":"River Lane"}]},"questions":[{"id":"l-19","number":19,"kind":"match","prompt":"Library"},{"id":"l-20","number":20,"kind":"match","prompt":"Car park"},{"id":"l-21","number":21,"kind":"match","prompt":"Post office"},{"id":"l-22","number":22,"kind":"match","prompt":"Sports hall"},{"id":"l-23","number":23,"kind":"match","prompt":"Bakery"}],"audio":"t10/l4.mp3","audioAt":{"19":24,"20":38,"21":50,"22":61,"23":73}},{"id":"l5","index":5,"instruction":"You will hear three extracts. Choose the correct answer (A, B or C) for each question. There are","emphasis":"TWO questions for each extract","durationSec":117,"questions":[{"id":"l-24","number":24,"kind":"mcq","prompt":"Why did Laura apply for the job at the cinema?","options":[{"key":"A","text":"to meet new people"},{"key":"B","text":"to pay for driving lessons"},{"key":"C","text":"to watch films for free"}],"group":"Extract One"},{"id":"l-25","number":25,"kind":"mcq","prompt":"What does Laura dislike about the job?","options":[{"key":"A","text":"working late at night"},{"key":"B","text":"her manager"},{"key":"C","text":"cleaning the cinema"}],"group":"Extract One"},{"id":"l-26","number":26,"kind":"mcq","prompt":"How did Rustam start keeping bees?","options":[{"key":"A","text":"His grandfather left him some hives."},{"key":"B","text":"He took a course at college."},{"key":"C","text":"He read a book about bees."}],"group":"Extract Two"},{"id":"l-27","number":27,"kind":"mcq","prompt":"According to Rustam, the biggest danger for bees today is","options":[{"key":"A","text":"cold weather."},{"key":"B","text":"complaints from neighbours."},{"key":"C","text":"chemicals used on farms."}],"group":"Extract Two"},{"id":"l-28","number":28,"kind":"mcq","prompt":"Why has the school trip been postponed?","options":[{"key":"A","text":"The bus was booked too late."},{"key":"B","text":"The museum is closed for repairs."},{"key":"C","text":"Not enough students signed up."}],"group":"Extract Three"},{"id":"l-29","number":29,"kind":"mcq","prompt":"What must every student bring on the day of the trip?","options":[{"key":"A","text":"a packed lunch"},{"key":"B","text":"a signed letter from parents"},{"key":"C","text":"a notebook"}],"group":"Extract Three"}],"audio":"t10/l5.mp3","audioAt":{"24":23,"25":37,"26":58,"27":68,"28":92,"29":103}},{"id":"l6","index":6,"title":"The history of tea","instruction":"You will hear a part of a lecture. Fill in the missing information. Write","emphasis":"no more than ONE WORD","durationSec":77,"questions":[{"id":"l-30","number":30,"kind":"gap","prompt":"In ancient China, tea was first drunk as a"},{"id":"l-31","number":31,"kind":"gap","prompt":"Tea reached Europe in the 17th century with Dutch"},{"id":"l-32","number":32,"kind":"gap","prompt":"At first, tea in Britain was very"},{"id":"l-33","number":33,"kind":"gap","prompt":"Afternoon tea was made fashionable by a"},{"id":"l-34","number":34,"kind":"gap","prompt":"Tea bags were invented by accident in"},{"id":"l-35","number":35,"kind":"gap","prompt":"Before drying, black tea leaves are fully"}],"audio":"t10/l6.mp3","audioAt":{"30":15,"31":26,"32":33,"33":42,"34":52,"35":62}}],"reading":[{"id":"r1","index":1,"title":"Why we need sleep","instruction":"Read the text. Fill in each gap with ONE word. You must use a word which is somewhere in the rest of the text.","passage":[{"label":"1","text":"Most adults need between seven and nine hours of sleep every night. However, many (1) ______ get much less than this, especially during busy weeks at work. Scientists say that sleep is not a waste of time. While we sleep, the (2) ______ sorts and stores what we have learned during the day. That is why students who sleep well are more likely to remember new information."},{"label":"2","text":"Lack of sleep also affects our mood and makes us more (3) ______ to make careless mistakes. Experts recommend going to bed at the same (4) ______ every evening. It also helps to switch off phones and other (5) ______ an hour before bed, because the light from screens keeps the brain awake."},{"label":"3","text":"Finally, a cool, dark and quiet (6) ______ helps most people fall asleep faster. If your bedroom is noisy, earplugs can make a big difference. Small changes like these can help adults, students and even busy workers feel more rested."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"However, many (1) ______ get much less than this."},{"id":"r-2","number":2,"kind":"gap","prompt":"While we sleep, the (2) ______ sorts and stores what we have learned."},{"id":"r-3","number":3,"kind":"gap","prompt":"It makes us more (3) ______ to make careless mistakes."},{"id":"r-4","number":4,"kind":"gap","prompt":"Go to bed at the same (4) ______ every evening."},{"id":"r-5","number":5,"kind":"gap","prompt":"Switch off phones and other (5) ______ an hour before bed."},{"id":"r-6","number":6,"kind":"gap","prompt":"A cool, dark and quiet (6) ______ helps you fall asleep."}]},{"id":"r2","index":2,"title":"Weekend activities","instruction":"Read the texts 7–14 and the statements A–J. Decide which text matches the situation in each statement. Each statement can be used ONCE only. There are TWO extra statements.","passage":[{"label":"7","text":"CHIMGAN HIKING CLUB — Guided mountain walks every Saturday. Beginners welcome. Transport from the city is included in the price. Bring strong shoes and water."},{"label":"8","text":"RIVERSIDE COOKING SCHOOL — Learn to cook plov and other national dishes in a small group. All ingredients provided. Take your dishes home with you."},{"label":"9","text":"CITY PHOTO WALK — Discover the hidden corners of the old town with a professional photographer who will show you how to take better pictures. Bring your camera or phone."},{"label":"10","text":"GREEN VALLEY FARM — Pick your own apples and cherries. Children under seven enter free. Fresh juice and pastries in our café."},{"label":"11","text":"SUNDAY CHESS CAFÉ — Friendly games with players of all levels. Weekly tournaments with prizes for the winners. Coffee is included in the entry price."},{"label":"12","text":"LAKESIDE YOGA — Outdoor classes at 7 am by the water. Mats available to rent. Classes are cancelled in bad weather."},{"label":"13","text":"ART IN THE PARK — Painting workshops for the whole family. All materials provided. The best pictures will be shown in our autumn exhibition at the city gallery."},{"label":"14","text":"NIGHT SKY TOURS — Watch the stars and planets through powerful telescopes, far from the city lights. Warm clothes recommended. Trips start at 10 pm."}],"choices":[{"key":"A","text":"You want to cook traditional food."},{"key":"B","text":"You would like to compete to win something."},{"key":"C","text":"You want to exercise early in the day near water."},{"key":"D","text":"You don't want to organise your own travel."},{"key":"E","text":"Your work may be seen by the public."},{"key":"F","text":"Young children can visit without paying."},{"key":"G","text":"You are interested in astronomy."},{"key":"H","text":"You want to learn how to take better photos."},{"key":"I","text":"You want to learn to swim."},{"key":"J","text":"You want to stay overnight in the mountains."}],"questions":[{"id":"r-7","number":7,"kind":"match","prompt":"Text 7"},{"id":"r-8","number":8,"kind":"match","prompt":"Text 8"},{"id":"r-9","number":9,"kind":"match","prompt":"Text 9"},{"id":"r-10","number":10,"kind":"match","prompt":"Text 10"},{"id":"r-11","number":11,"kind":"match","prompt":"Text 11"},{"id":"r-12","number":12,"kind":"match","prompt":"Text 12"},{"id":"r-13","number":13,"kind":"match","prompt":"Text 13"},{"id":"r-14","number":14,"kind":"match","prompt":"Text 14"}]},{"id":"r3","index":3,"title":"The rise of urban farming","instruction":"Read the text and choose the correct heading for each paragraph from the list of headings. There are more headings than paragraphs, so you will not use all of them.","passage":[{"label":"I","text":"Look up in many modern cities and you may see vegetables growing where you least expect them: on rooftops, balconies and even the walls of car parks. Empty spaces that were once ignored are being turned into small farms, and city planners are starting to see them as a valuable resource rather than wasted land."},{"label":"II","text":"Supporters say urban farms are good for the environment. Food grown in the city does not need to be transported hundreds of kilometres by lorry, which means less fuel and less pollution. Green roofs also keep buildings cooler in summer and help rainwater drain away more slowly."},{"label":"III","text":"There are social benefits too. Community gardens give neighbours who have never spoken a reason to meet. Older residents share their knowledge with children, who learn where their food comes from. In some cities, volunteers grow vegetables for local families who cannot afford fresh food."},{"label":"IV","text":"Some of the most exciting projects use no earth at all. In so-called vertical farms, plants grow in water rich in nutrients, stacked on shelves inside old warehouses. Special lights replace the sun, and computers control the temperature, so crops can be harvested all year round."},{"label":"V","text":"However, urban farming has its critics. Land and electricity in cities are expensive, and indoor farms use a great deal of energy. So far, they can only grow certain crops, such as salad leaves and herbs, profitably. Wheat, rice and potatoes still need large fields."},{"label":"VI","text":"Even so, many experts believe urban farms will play a bigger role in the coming decades. Several governments now offer grants for green roofs, and some schools have started their own gardens. As cities continue to grow, finding new ways to feed their residents may become a necessity rather than a hobby."}],"choices":[{"key":"A","text":"Growing without soil"},{"key":"B","text":"Not without difficulties"},{"key":"C","text":"A new use for city spaces"},{"key":"D","text":"Bringing people together"},{"key":"E","text":"Why farmers are leaving the countryside"},{"key":"F","text":"Good news for the planet"},{"key":"G","text":"What lies ahead"},{"key":"H","text":"The most profitable crops"}],"questions":[{"id":"r-15","number":15,"kind":"match","prompt":"Paragraph I"},{"id":"r-16","number":16,"kind":"match","prompt":"Paragraph II"},{"id":"r-17","number":17,"kind":"match","prompt":"Paragraph III"},{"id":"r-18","number":18,"kind":"match","prompt":"Paragraph IV"},{"id":"r-19","number":19,"kind":"match","prompt":"Paragraph V"},{"id":"r-20","number":20,"kind":"match","prompt":"Paragraph VI"}]},{"id":"r4","index":4,"title":"Two wheels","instruction":"Read the text. For questions 21–24, choose the correct answer A, B, C or D. For questions 25–29, decide if the statements agree with the information in the text.","passage":[{"label":"1","text":"I was twelve when I found an old bicycle under a dusty sheet in my grandfather’s garage. It had a heavy black frame, a leather seat and a little bell that still worked. My grandfather laughed when he saw my face and said it had been his pride and joy as a young man. From that day on I wanted to know everything about bicycles, and I have been collecting them for almost thirty years."},{"label":"2","text":"The story of the bicycle begins in 1817 in the German city of Mannheim, where an inventor called Karl Drais built what he called a “running machine”. It had two wooden wheels and handlebars, but no pedals: the rider sat on it and pushed it along with his feet. It was fast on good roads, but the roads of the time were rarely good, and the fashion soon passed."},{"label":"3","text":"Pedals arrived in the 1860s, and soon afterwards came the strange-looking “penny-farthing”, with its enormous front wheel and tiny back one. The large wheel made it fast, but the rider sat so high above the ground that any stone in the road could throw him over the handlebars. It was also expensive, so it remained a toy for young men with money and courage."},{"label":"4","text":"The real revolution came in the 1880s with the “safety bicycle”, which had two wheels of the same size and a chain that turned the back wheel. A few years later, a Scottish vet, John Dunlop, developed air-filled rubber tyres while trying to make his son’s tricycle more comfortable. Cycling suddenly became cheap, safe and pleasant."},{"label":"5","text":"The effect on society was enormous, especially for women. For the first time, many women could travel on their own, without a horse or a companion, and clothing changed to make riding easier. Some historians argue that the bicycle did more for women’s independence than any law of the time. Today, when I ride my grandfather’s old bicycle through the park, I like to think of all the journeys it has made possible."}],"questions":[{"id":"r-21","number":21,"kind":"mcq","prompt":"The writer became interested in bicycles when she","options":[{"key":"A","text":"was given one as a birthday present."},{"key":"B","text":"found an old one in a garage."},{"key":"C","text":"saw a collection in a museum."},{"key":"D","text":"learnt to ride with her grandfather."}]},{"id":"r-22","number":22,"kind":"mcq","prompt":"The “running machine” did not have","options":[{"key":"A","text":"wheels."},{"key":"B","text":"a seat."},{"key":"C","text":"pedals."},{"key":"D","text":"handlebars."}]},{"id":"r-23","number":23,"kind":"mcq","prompt":"The penny-farthing was dangerous because","options":[{"key":"A","text":"its brakes often failed."},{"key":"B","text":"the rider sat very high above the ground."},{"key":"C","text":"its wheels were made of wood."},{"key":"D","text":"it was too heavy to control."}]},{"id":"r-24","number":24,"kind":"mcq","prompt":"According to the text, the bicycle changed women’s lives by","options":[{"key":"A","text":"creating new jobs in factories."},{"key":"B","text":"making horses cheaper."},{"key":"C","text":"allowing them to travel independently."},{"key":"D","text":"changing the laws of the time."}]},{"id":"r-25","number":25,"kind":"tfng","prompt":"The writer’s grandfather used his bicycle to get to work."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The first bicycle-like machine was built in Germany."},{"id":"r-27","number":27,"kind":"tfng","prompt":"Most people could afford a penny-farthing."},{"id":"r-28","number":28,"kind":"tfng","prompt":"Air-filled tyres were developed by an animal doctor."},{"id":"r-29","number":29,"kind":"tfng","prompt":"Today there are more bicycles than cars in the world."}]},{"id":"r5","index":5,"title":"Cities of the Silk Road","instruction":"Read the text. For questions 30–33, fill in the missing information. Write no more than ONE WORD and / or A NUMBER. For questions 34–35, choose the correct answer A, B, C or D.","passage":[{"label":"1","text":"For more than fifteen centuries, the network of trade routes known as the Silk Road linked China with the Mediterranean. Silk was only one of many goods carried along it: spices, paper, glass, horses and precious stones all travelled thousands of kilometres from one market to the next. Few merchants made the whole journey themselves; most goods changed hands many times along the way."},{"label":"2","text":"Travel was slow and dangerous. A camel caravan usually covered about thirty kilometres a day, and travellers faced deserts, mountain passes and bandits. To make the journey possible, rulers built caravanserais — large inns with thick walls where people and animals could rest safely for the night. Some of these buildings can still be seen in Uzbekistan today."},{"label":"3","text":"Cities such as Samarkand and Bukhara grew rich from this trade. Their markets were full of languages from across Asia and Europe, and with the goods came new ideas, religions and scientific knowledge. Scholars from these cities made important discoveries in mathematics, astronomy and medicine that later influenced the rest of the world."},{"label":"4","text":"From the fifteenth century onwards, however, European ships found routes to Asia by sea. Ships could carry far more goods than camels, and the journey was cheaper, so the old land routes slowly lost their importance. Today, the great cities of the Silk Road attract a different kind of traveller: tourists who come to admire the blue domes and busy bazaars that tell the story of this remarkable past."}],"questions":[{"id":"r-30","number":30,"kind":"gap","prompt":"The Silk Road connected China with the"},{"id":"r-31","number":31,"kind":"gap","prompt":"A caravan travelled about … kilometres a day."},{"id":"r-32","number":32,"kind":"gap","prompt":"Travellers rested in inns called"},{"id":"r-33","number":33,"kind":"gap","prompt":"Along with goods, people exchanged new"},{"id":"r-34","number":34,"kind":"mcq","prompt":"Why did the land routes become less important?","options":[{"key":"A","text":"Wars closed the borders between countries."},{"key":"B","text":"Silk went out of fashion in Europe."},{"key":"C","text":"Transport by sea was cheaper and carried more."},{"key":"D","text":"The cities stopped building caravanserais."}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":[{"key":"A","text":"to advertise tours to Samarkand and Bukhara"},{"key":"B","text":"to explain how trade shaped the history of Silk Road cities"},{"key":"C","text":"to compare land travel with sea travel"},{"key":"D","text":"to criticise modern tourism in Central Asia"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1","kind":"Letter","context":"You joined an online English course a month ago, but you have had several problems with the lessons and the website.","prompt":"Write an email to the course manager. In your email:\n- explain why you joined the course;\n- describe the problems you have had;\n- say what you would like the manager to do.\nWrite about 150 words in an appropriate format and style.","targetWords":150,"minWords":120,"weight":1},{"id":"w2","index":2,"label":"Task 2","kind":"Essay","prompt":"Some people believe that young people should take a year off to work or travel before starting university. Others think they should begin their studies immediately after school.\n\nDiscuss both views and give your opinion. Write at least 250 words in an appropriate style and format.","targetWords":250,"minWords":250,"weight":2}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"Tell me about your family.","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"What do you like to do in your free time?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"What kind of food do you enjoy most?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Where would you prefer to work? Why?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Do you think more people will work from home in the future?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe an important day in your life. Say when it was, what happened and why it was important to you.","image":"A young man celebrating his graduation with his family","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Tourism is good for a country. For: it creates jobs and brings money. Against: it damages nature and raises prices for local people. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
