values ('t10', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"A","explanation":"Kitob yo'qolgani uchun uzr so'ralmoqda — to'g'ri javob tinchlantiruvchi replika."},"l-4":{"answer":"C"},"l-5":{"answer":"B"},"l-6":{"answer":"A","explanation":"\"Yes, I could\" grammatik jihatdan mos, lekin savolga javob bermaydi — joy so'ralmoqda."},"l-7":{"answer":"B","explanation":"Konsert bekor qilingan, shuning uchun soyabon olib kelishning ma'nosi yo'q."},"l-8":{"answer":"A"},"l-9":{"answer":"reception"},"l-10":{"answer":"9|nine","explanation":"Avval dam olish kunlari uchun 7 aytiladi, ish kunlari esa 9 da yopiladi."},"l-11":{"answer":"2|two"},"l-12":{"answer":"Thursday"},"l-13":{"answer":"towel"},"l-14":{"answer":"10|ten","explanation":"15 foiz faqat birinchi oy uchun edi va endi amal qilmaydi."},"l-15":{"answer":"C"},"l-16":{"answer":"A"},"l-17":{"answer":"D","explanation":"\"Exhibits\", \"please don't touch\" va \"guided tour\" — muzey belgilari."},"l-18":{"answer":"F"},"l-19":{"answer":"B"},"l-20":{"answer":"H","explanation":"\"Directly behind the town hall\" — ratusha orqasida, ya'ni janubida."},"l-21":{"answer":"C"},"l-22":{"answer":"G"},"l-23":{"answer":"E"},"l-24":{"answer":"B","explanation":"Bepul filmlar haqida gapiradi, lekin asosiy sabab — haydovchilik darslari uchun pul."},"l-25":{"answer":"A"},"l-26":{"answer":"A"},"l-27":{"answer":"C","explanation":"Ob-havo va qo'shnilar ham tilga olinadi, lekin \"the real danger\" — pestitsidlar."},"l-28":{"answer":"B"},"l-29":{"answer":"B","explanation":"Tushlik ixtiyoriy, daftar esa maktab beradi — majburiysi ota-ona imzolagan xat."},"l-30":{"answer":"medicine"},"l-31":{"answer":"traders|merchants"},"l-32":{"answer":"expensive"},"l-33":{"answer":"duchess"},"l-34":{"answer":"America|USA|US"},"l-35":{"answer":"oxidised|oxidized","explanation":"Yashil choy bargi oksidlanmaydi, qora choy esa to'liq oksidlanadi."},"r-1":{"answer":"adults"},"r-2":{"answer":"brain"},"r-3":{"answer":"likely","explanation":"So'z matnning o'zida bor: \"are more likely to remember\"."},"r-4":{"answer":"time"},"r-5":{"answer":"screens"},"r-6":{"answer":"bedroom"},"r-7":{"answer":"D","explanation":"Tog'da tunab qolish (J) haqida gap yo'q — \"transport is included\"."},"r-8":{"answer":"A"},"r-9":{"answer":"H"},"r-10":{"answer":"F"},"r-11":{"answer":"B"},"r-12":{"answer":"C"},"r-13":{"answer":"E"},"r-14":{"answer":"G"},"r-15":{"answer":"C"},"r-16":{"answer":"F"},"r-17":{"answer":"D"},"r-18":{"answer":"A"},"r-19":{"answer":"B","explanation":"Paragrafda foydali ekinlar tilga olinadi, lekin asosiy fikr — muammolar (H emas)."},"r-20":{"answer":"G"},"r-21":{"answer":"B"},"r-22":{"answer":"C"},"r-23":{"answer":"B"},"r-24":{"answer":"C","explanation":"Matnda qonunlar bilan solishtiriladi, lekin velosiped qonunni o'zgartirgan deyilmaydi."},"r-25":{"answer":"No Information","explanation":"Bobosi velosipedni yaxshi ko'rgani aytiladi, lekin ishga qanday borgani haqida ma'lumot yo'q."},"r-26":{"answer":"True"},"r-27":{"answer":"False"},"r-28":{"answer":"True","explanation":"Vet — veterinar, ya'ni hayvonlar shifokori."},"r-29":{"answer":"No Information"},"r-30":{"answer":"Mediterranean"},"r-31":{"answer":"30|thirty"},"r-32":{"answer":"caravanserais|caravanserai"},"r-33":{"answer":"ideas"},"r-34":{"answer":"C"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"woman","text":"Would you mind if I opened the window?","question":1},{"voice":"man","text":"How long have you been learning English?","question":2},{"voice":"woman","text":"I'm so sorry, but I'm afraid I've lost the book you lent me.","question":3},{"voice":"man","text":"Shall we take a taxi to the station, or walk?","question":4},{"voice":"woman","text":"Congratulations on passing your driving test!","question":5},{"voice":"man","text":"Excuse me, could you tell me where the nearest pharmacy is?","question":6},{"voice":"woman","text":"Have you heard? Tonight's concert has been cancelled because of the rain.","question":7},{"voice":"man","text":"Do you fancy coming round to our place for dinner on Friday?","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a guide talking to new members of a sports centre. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"woman","text":"Good morning, everyone, and welcome to City Sports Centre. I'm Nodira, and I'll tell you a few things you need to know before you start."},{"voice":"woman","text":"First of all, your membership card. Please don't leave it at home, because you need to show it at the reception every time you come in. The security guard at the door can't check it for you.","question":9},{"voice":"woman","text":"Now, the swimming pool. At weekends it closes quite early, at seven in the evening, but from Monday to Friday you can swim until nine p.m.","question":10},{"voice":"woman","text":"There are lockers in both changing rooms. They're free to use, but you pay a deposit of two pounds, which you get back when you return the key.","question":11},{"voice":"woman","text":"Lots of you have asked about yoga. The advanced class is on Tuesday evenings, and the beginners' class is every Thursday, so I'd recommend starting there.","question":12},{"voice":"woman","text":"In the gym, please always use your own towel on the machines. We don't provide them, I'm afraid, but you can buy one in our shop.","question":13},{"voice":"woman","text":"And finally, our café. During your first month there was a special offer of fifteen per cent off, but that's finished now. All members get ten per cent off everything, all year round. Enjoy your training!","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"man","text":"Good evening, and welcome. I can see your booking here: a double room for three nights. Here's your key card. Breakfast is served from seven in the restaurant, and the lift is just behind you."},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"woman","text":"Excuse me, is this the right platform for Samarkand? The board says the eight fifteen is delayed. Oh, it's leaving from platform four now? Thanks, I'd better run, it's going in two minutes."},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"man2","text":"Ladies and gentlemen, the guided tour of the exhibits will begin in five minutes by the main staircase. Please don't touch any of the objects, and remember that photography with a flash is not allowed in this hall."},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"woman2","text":"Right, we've got the milk and the bread. Can you go and get some tomatoes from the vegetable section? I'll queue at the checkout. Oh, and don't forget, the eggs are on special offer today."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"man","text":"Hello and welcome to our town. I'm going to tell you where some useful places are. We're standing at the entrance of the town hall, on the south side of Main Street."},{"voice":"man","text":"First, the library. Walk to the crossroads where North Road meets Main Street. The library is on the corner, on the north side of Main Street and just to the west of North Road.","question":19},{"voice":"man","text":"If you come by car, don't park on Main Street. The car park is directly behind the town hall, on its south side, and it's free on Sundays.","question":20},{"voice":"man","text":"The post office is a short walk up North Road. Go north from the crossroads, and you'll see it on your right, about halfway up the road.","question":21},{"voice":"man","text":"For the sports hall, go east along Main Street and turn right into River Lane. Walk down River Lane, and the sports hall is near the end, on your left-hand side.","question":22},{"voice":"man","text":"And finally, the best bakery in town. It's at the western end of Main Street, on the south side, opposite the bank. You'll smell the fresh bread before you see it!","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two friends talking about a part-time job."},{"voice":"man","text":"So, Laura, how's the new job at the cinema? I bet you watch all the new films for free."},{"voice":"woman","text":"Well, yes, staff can see films for free, which is nice. But honestly, that's not why I applied. Driving lessons are so expensive, and I want to pass my test before the summer, so I need the money.","question":24},{"voice":"woman","text":"The manager's really kind, and I don't mind cleaning the seats after each show. What I hate is the late shifts. Sometimes I don't finish until after midnight, and I'm exhausted the next day.","question":25},{"voice":"narrator","text":"Extract two. You will hear part of a radio interview with a beekeeper."},{"voice":"woman2","text":"Rustam, you've kept bees for twenty years. How did it all start?"},{"voice":"man2","text":"My grandfather was a beekeeper, and when he died he left me his three hives. I'd never taken a course or read a book about bees, so I learnt everything by making mistakes!","question":26},{"voice":"man2","text":"People think cold winters are the main problem, but bees cope with weather quite well. And yes, sometimes neighbours complain. But the real danger is the chemicals that farmers spray on their fields. They kill whole colonies.","question":27},{"voice":"narrator","text":"Extract three. You will hear a teacher talking to a student about a school trip."},{"voice":"woman","text":"Miss Karimova, are we still going to the history museum on Friday?"},{"voice":"woman3","text":"I'm afraid not, Aziz. We booked the bus in good time and lots of students signed up, but the museum is closed for repairs until next month. So we've moved the trip to the fourteenth.","question":28},{"voice":"woman3","text":"You can bring a packed lunch if you like, and the school will give everyone a notebook. But you must bring the letter signed by your parents, or you can't come.","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Good afternoon. Today's lecture is about one of the world's favourite drinks: tea."},{"voice":"man3","text":"According to legend, tea was discovered in China nearly five thousand years ago. At first people didn't drink it for pleasure. It was used as a medicine, to help with tiredness and stomach problems.","question":30},{"voice":"man3","text":"Tea didn't reach Europe until the seventeenth century, when Dutch traders brought it from Asia to Amsterdam.","question":31},{"voice":"man3","text":"When tea arrived in Britain, it was very expensive, so only rich families could afford it. They often kept their tea in locked wooden boxes.","question":32},{"voice":"man3","text":"The famous tradition of afternoon tea started in the eighteen-forties. It was made fashionable by a duchess, who felt hungry in the long hours between lunch and dinner.","question":33},{"voice":"man3","text":"Tea bags, by the way, were invented by accident in America. A tea seller sent samples to his customers in small silk bags, and they put the bags straight into hot water.","question":34},{"voice":"man3","text":"Finally, what makes black tea different from green tea? Green tea leaves are dried quickly, but black tea leaves are fully oxidised before drying, which gives them their dark colour and strong taste.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

