insert into public.test_keys (test_id, keys, scripts)
values ('t11', $json${"l-1":{"answer":"B"},"l-2":{"answer":"C"},"l-3":{"answer":"A"},"l-4":{"answer":"B","explanation":"Taksi qimmat, mashinada joy yo'q — poyezd."},"l-5":{"answer":"C"},"l-6":{"answer":"B"},"l-7":{"answer":"B"},"l-8":{"answer":"B","explanation":"Sakkiz kishi taklif qilingan, lekin ikki kishi kela olmaydi."},"l-9":{"answer":"6 am|6 a.m."},"l-10":{"answer":"25","explanation":"Odatiy narx 30, lekin talabalar uchun 25."},"l-11":{"answer":"photo|photograph"},"l-12":{"answer":"free"},"l-13":{"answer":"Wednesday|Wednesdays"},"l-14":{"answer":"reception"},"l-15":{"answer":"towel"},"l-16":{"answer":"back"},"l-17":{"answer":"A"},"l-18":{"answer":"B"},"l-19":{"answer":"A"},"l-20":{"answer":"A"},"l-21":{"answer":"B"},"l-22":{"answer":"A"},"l-23":{"answer":"B"},"l-24":{"answer":"B"},"l-25":{"answer":"C"},"l-26":{"answer":"B"},"l-27":{"answer":"B"},"l-28":{"answer":"clock|clock tower"},"l-29":{"answer":"7|seven"},"l-30":{"answer":"market"},"l-31":{"answer":"B"},"l-32":{"answer":"B"},"l-33":{"answer":"B"},"l-34":{"answer":"B"},"l-35":{"answer":"B"},"r-1":{"answer":"pool"},"r-2":{"answer":"sixteen|16"},"r-3":{"answer":"May"},"r-4":{"answer":"races"},"r-5":{"answer":"T-shirt|tshirt"},"r-6":{"answer":"area"},"r-7":{"answer":"allowed"},"r-8":{"answer":"B"},"r-9":{"answer":"B"},"r-10":{"answer":"B"},"r-11":{"answer":"B"},"r-12":{"answer":"B"},"r-13":{"answer":"B"},"r-14":{"answer":"A"},"r-15":{"answer":"B"},"r-16":{"answer":"A"},"r-17":{"answer":"B"},"r-18":{"answer":"B"},"r-19":{"answer":"A"},"r-20":{"answer":"A"},"r-21":{"answer":"A"},"r-22":{"answer":"True"},"r-23":{"answer":"False"},"r-24":{"answer":"True","explanation":"C paragrafi: suv sathi ko'tarilgan, baliqlar qaytgan."},"r-25":{"answer":"Not given"},"r-26":{"answer":"True"},"r-27":{"answer":"B"},"r-28":{"answer":"B"},"r-29":{"answer":"B"},"r-30":{"answer":"C"},"r-31":{"answer":"A"},"r-32":{"answer":"B"},"r-33":{"answer":"B"},"r-34":{"answer":"C"},"r-35":{"answer":"A"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. What does the man want to buy?","question":1},{"voice":"woman","text":"Can I help you? Are you looking for a jacket? They are all half price today."},{"voice":"man","text":"Thanks, but I've got enough jackets. I need a pair of shoes for my sister's wedding. Something black and smart."},{"voice":"narrator","text":"Question 2. Where will the friends meet?","question":2},{"voice":"man","text":"Shall we meet at the bus stop and walk to the park together?"},{"voice":"woman","text":"It's quicker if I go straight there. Let's meet at the park gate, the main one opposite the cinema."},{"voice":"narrator","text":"Question 3. What is the woman’s new job?","question":3},{"voice":"man","text":"I heard you left the hospital. Are you still working as a nurse?"},{"voice":"woman","text":"No, I've changed careers completely. I'm teaching English at a secondary school now, and I love it."},{"voice":"narrator","text":"Question 4. How will they get to the airport?","question":4},{"voice":"woman","text":"Should we take a taxi to the airport?"},{"voice":"man","text":"It's far too expensive at that time, and my car is full of boxes. Let's take the train. It's fast and it goes right to the terminal."},{"voice":"narrator","text":"Question 5. What did the boy forget?","question":5},{"voice":"woman","text":"Have you got everything for school? Your homework? Your lunch box?"},{"voice":"man2","text":"Yes, Mum, they're both in my bag. Oh no, I've left my sports kit in the hall, and we've got football today!"},{"voice":"narrator","text":"Question 6. When is the concert?","question":6},{"voice":"man","text":"Is the concert on Friday evening?"},{"voice":"woman","text":"No, Friday is the rehearsal. The concert is on Saturday, and on Sunday they're playing in another city."},{"voice":"narrator","text":"Question 7. What is wrong with the room?","question":7},{"voice":"woman","text":"Excuse me, I'd like to change rooms. It's big and warm enough, but it's right above the street, and the traffic is so loud I can't sleep."},{"voice":"narrator","text":"Question 8. How many people are coming to dinner?","question":8},{"voice":"man","text":"How many people did you invite to dinner on Saturday?"},{"voice":"woman","text":"I invited eight, but the Rahimovs can't come because they'll be away. So we'll be six."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call to a fitness club. Complete the notes. Write no more than two words."},{"voice":"man","text":"Sunrise Fitness Club, how can I help?"},{"voice":"woman","text":"Hi, I'm thinking of joining. What are your opening hours?"},{"voice":"man","text":"At weekends we open at eight, but on weekdays we open at six a.m. and close at ten at night.","question":9},{"voice":"woman","text":"And how much is the membership?"},{"voice":"man","text":"The standard fee is thirty pounds a month. Are you a student? Then it's twenty-five pounds.","question":10},{"voice":"woman","text":"Yes, I am. What do I need to join?"},{"voice":"man","text":"Just bring your student card and a recent photo for your membership card.","question":11},{"voice":"man","text":"Also, your first personal training session is free, so a trainer can make a plan for you.","question":12},{"voice":"woman","text":"Do you have yoga classes?"},{"voice":"man","text":"Yes, on Wednesday evenings. We used to have them on Mondays, but Wednesday is more popular.","question":13},{"voice":"woman","text":"Where can I leave my things?"},{"voice":"man","text":"The lockers are next to the reception, and they are free to use.","question":14},{"voice":"man","text":"We don't provide towels, so please remember to bring a towel with you.","question":15},{"voice":"woman","text":"And is there parking?"},{"voice":"man","text":"Yes, there's a free car park at the back of the building. The front is for buses only.","question":16},{"voice":"woman","text":"Great, thanks a lot."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about their holidays. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"The beaches were nice, and people were friendly enough. But what I'll remember is the food. Every meal was an adventure, and I tried dishes I'd never heard of."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"The hotel was lovely and the weather was perfect. The only problem was that the airline lost my suitcase, and I spent the first three days in the same clothes."},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"woman2","text":"My friends couldn't get time off work, so for the first time I went on my own. I was nervous at first, but it was the best trip of my life."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"man2","text":"Beaches bore me, and big cities are too crowded. Give me the mountains any time: fresh air, long walks and complete silence."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"man3","text":"It wasn't cheap, but it was worth every penny. My only complaint is that five days wasn't enough. I needed at least two weeks."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"woman3","text":"I loved the food, and I went diving twice. But I couldn't talk to anyone, so I want to go back after I've learned some of the language."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear an interview with a university librarian. Choose the correct answer."},{"voice":"man","text":"My guest today is Mrs Nazarova, head librarian at the State University. How do students use the library today?"},{"voice":"woman","text":"Far fewer students borrow books than before, and most print at home. Today they mainly come to study in groups. Our group rooms are always full.","question":23},{"voice":"woman","text":"The biggest change has been digital resources. Students can read thousands of journals and e-books online, even at home.","question":24},{"voice":"man","text":"What do students complain about?"},{"voice":"woman","text":"Sometimes the Wi-Fi, and sometimes noise. But the most common complaint is that there aren't enough seats, especially before exams.","question":25},{"voice":"man","text":"Any plans for the future?"},{"voice":"woman","text":"People keep asking for a café, and some want us open all night. But our main plan is to build a completely quiet floor for individual study.","question":26},{"voice":"man","text":"Do paper books have a future?"},{"voice":"woman","text":"Definitely. Many students tell me they concentrate better with paper. I think printed books will remain important for a long time.","question":27},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear a guide at the start of a walking tour. Complete the notes. Write one word or a number."},{"voice":"man","text":"Good morning, everyone! If you're here for the Old Town walking tour, you're in the right place: we always meet here, at the old clock tower.","question":28},{"voice":"man","text":"The tour lasts about two hours and has seven stops, including the old mosque and the craftsmen's street.","question":29},{"voice":"man","text":"We'll finish at the market, where you can try local bread and dried fruit. Let's go!","question":30},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a lecture about social media. Choose the correct answer."},{"voice":"woman","text":"Good afternoon. Let's start with a number. Studies show that young people spend on average three hours a day on social media. For some, it's much more, even six hours.","question":31},{"voice":"woman","text":"Many people worry about privacy or losing sleep, and these are real problems. But I believe the main risk is that we constantly compare ourselves to others, and that makes us feel worse about our own lives.","question":32},{"voice":"woman","text":"Of course, social media isn't all bad. It can be very positive when it helps people stay in touch with family and friends who live far away.","question":33},{"voice":"woman","text":"In one study, students stopped using social media for a week. Surprisingly, they didn't feel bored or stressed. Most said they felt happier and slept better.","question":34},{"voice":"woman","text":"So, do you need to delete all your apps? No. My recommendation is simpler: turn off notifications, and decide yourself when to check your phone. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

