values ('t12', 12, 'Mock Test #12', 8, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":159,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"What will the woman bring to the party?","options":[{"key":"A","text":"A cake"},{"key":"B","text":"Some drinks"},{"key":"C","text":"Some fruit"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"Which bus should the man take?","options":[{"key":"A","text":"Number 12"},{"key":"B","text":"Number 21"},{"key":"C","text":"Number 7"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"What is the weather going to be like tomorrow?","options":[{"key":"A","text":"Rainy"},{"key":"B","text":"Sunny"},{"key":"C","text":"Windy"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"Why is the man late?","options":[{"key":"A","text":"He overslept"},{"key":"B","text":"His train was cancelled"},{"key":"C","text":"He lost his wallet"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"What does the woman want to study?","options":[{"key":"A","text":"Medicine"},{"key":"B","text":"Law"},{"key":"C","text":"Architecture"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"How long will the repair take?","options":[{"key":"A","text":"Two days"},{"key":"B","text":"Five days"},{"key":"C","text":"A week"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"Where are the speakers?","options":[{"key":"A","text":"In a bank"},{"key":"B","text":"In a hotel"},{"key":"C","text":"In a pharmacy"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"What time is the appointment now?","options":[{"key":"A","text":"10:30"},{"key":"B","text":"11:00"},{"key":"C","text":"11:30"}]}],"audio":"t12/l1.mp3","audioAt":{"1":8,"2":26,"3":43,"4":64,"5":80,"6":100,"7":116,"8":136}},{"id":"l2","index":2,"title":"Greenway Language School — Enrolment","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":88,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Course level chosen:"},{"id":"l-10","number":10,"kind":"gap","prompt":"Classes are held on Tuesday and"},{"id":"l-11","number":11,"kind":"gap","prompt":"Class start time:"},{"id":"l-12","number":12,"kind":"gap","prompt":"Course fee: £"},{"id":"l-13","number":13,"kind":"gap","prompt":"Maximum students per class:"},{"id":"l-14","number":14,"kind":"gap","prompt":"Free extra activity:"},{"id":"l-15","number":15,"kind":"gap","prompt":"Placement test is taken"},{"id":"l-16","number":16,"kind":"gap","prompt":"Course books are included in the"}],"audio":"t12/l2.mp3","audioAt":{"9":19,"10":28,"11":35,"12":43,"13":55,"14":59,"15":69,"16":77}},{"id":"l3","index":3,"instruction":"You will hear six people talking about their hobbies. Choose the correct answer.","durationSec":90,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1 started painting because","options":[{"key":"A","text":"a friend advised her"},{"key":"B","text":"she wanted to relax"},{"key":"C","text":"she took a course at work"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 says the hardest thing about running is","options":[{"key":"A","text":"the weather"},{"key":"B","text":"getting up early"},{"key":"C","text":"staying motivated"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 collects","options":[{"key":"A","text":"old coins"},{"key":"B","text":"stamps"},{"key":"C","text":"vinyl records"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 learned to cook from","options":[{"key":"A","text":"videos online"},{"key":"B","text":"her grandmother"},{"key":"C","text":"a cookery school"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 enjoys chess mainly because it","options":[{"key":"A","text":"is cheap"},{"key":"B","text":"trains his memory"},{"key":"C","text":"helps him meet people"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 plans to","options":[{"key":"A","text":"sell his photos"},{"key":"B","text":"buy a new camera"},{"key":"C","text":"enter a competition"}]}],"audio":"t12/l3.mp3","audioAt":{"17":9,"18":23,"19":37,"20":51,"21":63,"22":73}},{"id":"l4","index":4,"instruction":"Listen to a radio interview with a young app developer. Choose the correct answer.","durationSec":91,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"Aziz got the idea for his app","options":[{"key":"A","text":"at school"},{"key":"B","text":"while travelling"},{"key":"C","text":"from his parents"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"The app helps users to","options":[{"key":"A","text":"learn languages"},{"key":"B","text":"find cheap transport"},{"key":"C","text":"split bills with friends"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"The biggest challenge at the start was","options":[{"key":"A","text":"money"},{"key":"B","text":"finding a team"},{"key":"C","text":"technical problems"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"How many people use the app now?","options":[{"key":"A","text":"Ten thousand"},{"key":"B","text":"Fifty thousand"},{"key":"C","text":"One hundred thousand"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"His advice to young people is to","options":[{"key":"A","text":"study programming early"},{"key":"B","text":"start with a small idea"},{"key":"C","text":"find investors quickly"}]}],"audio":"t12/l4.mp3","audioAt":{"23":17,"24":31,"25":46,"26":60,"27":73}},{"id":"l5","index":5,"title":"Hillside National Park — Visitor Information","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":47,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"The visitor centre closes at (pm)"},{"id":"l-29","number":29,"kind":"gap","prompt":"The easiest path is the"},{"id":"l-30","number":30,"kind":"gap","prompt":"Visitors must not feed the"}],"audio":"t12/l5.mp3","audioAt":{"28":9,"29":19,"30":35}},{"id":"l6","index":6,"instruction":"Listen to a talk about food waste. Choose the correct answer.","durationSec":63,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"According to the speaker, most food waste happens","options":[{"key":"A","text":"on farms"},{"key":"B","text":"in shops"},{"key":"C","text":"in homes"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"The most commonly wasted food is","options":[{"key":"A","text":"bread"},{"key":"B","text":"fruit"},{"key":"C","text":"meat"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"Many people misunderstand","options":[{"key":"A","text":"cooking times"},{"key":"B","text":"date labels"},{"key":"C","text":"portion sizes"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"The speaker suggests making","options":[{"key":"A","text":"a shopping list"},{"key":"B","text":"smaller meals"},{"key":"C","text":"home compost"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"The speaker thinks change must start with","options":[{"key":"A","text":"governments"},{"key":"B","text":"supermarkets"},{"key":"C","text":"individuals"}]}],"audio":"t12/l6.mp3","audioAt":{"31":7,"32":18,"33":28,"34":38,"35":47}}],"reading":[{"id":"r1","index":1,"title":"Notice: Summer Book Fair","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"The annual Summer Book Fair will take place in the Central Park pavilion from 12 to 14 July. Entry is free for everyone, and the fair opens at 10 am each day."},{"label":"B","text":"More than forty publishers will sell new and second-hand books at reduced prices. Local authors will sign copies of their latest novels on Saturday afternoon."},{"label":"C","text":"Children can join storytelling sessions in the green tent. Visitors are advised to bring cash, as some stalls do not accept cards."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"The fair is held in the Central Park"},{"id":"r-2","number":2,"kind":"gap","prompt":"Visitors do not have to pay for"},{"id":"r-3","number":3,"kind":"gap","prompt":"Books are sold at reduced"},{"id":"r-4","number":4,"kind":"gap","prompt":"Authors sign books on Saturday"},{"id":"r-5","number":5,"kind":"gap","prompt":"Storytelling takes place in the green"},{"id":"r-6","number":6,"kind":"gap","prompt":"Some stalls only accept"},{"id":"r-7","number":7,"kind":"gap","prompt":"Publishers will sell both new and"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Dear students, the chemistry lab will be closed on Friday for cleaning. Friday’s practical lesson will take place next Monday instead."},{"label":"B","text":"Lost: a black umbrella with a wooden handle, left in the library reading room on Tuesday. Please hand it in at the front desk."},{"label":"C","text":"Anna — I’ve booked the tennis court for 7, not 6. Can you bring the balls? I only have my racket."}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"Why will the lab be closed?","options":[{"key":"A","text":"For repairs"},{"key":"B","text":"For cleaning"},{"key":"C","text":"For an exam"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"When will the practical lesson happen?","options":[{"key":"A","text":"On Friday"},{"key":"B","text":"Next Monday"},{"key":"C","text":"Next Friday"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"What is special about the umbrella?","options":[{"key":"A","text":"Its colour"},{"key":"B","text":"Its handle"},{"key":"C","text":"Its size"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"Where should the umbrella be returned?","options":[{"key":"A","text":"To the reading room"},{"key":"B","text":"To the front desk"},{"key":"C","text":"To the owner"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"What time is the tennis court booked for?","options":[{"key":"A","text":"6 o’clock"},{"key":"B","text":"6:30"},{"key":"C","text":"7 o’clock"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"What should Anna bring?","options":[{"key":"A","text":"A racket"},{"key":"B","text":"Tennis balls"},{"key":"C","text":"Water"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message is written to a group of people?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"The Return of the Bicycle","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"In many cities, the bicycle is making a comeback. Sales of bikes, especially electric ones, have doubled in the past five years."},{"label":"B","text":"City councils are building protected cycle lanes, and some employers now pay staff a small bonus for cycling to work."},{"label":"C","text":"Critics point out that cycling is still dangerous where lanes are missing, and that winter weather keeps many riders off the road."},{"label":"D","text":"Even so, experts believe cycling will play a central role in the transport of the future, as long as investment continues."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"Which type of bike has become especially popular?","options":[{"key":"A","text":"Racing bikes"},{"key":"B","text":"Electric bikes"},{"key":"C","text":"Folding bikes"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"Bike sales have","options":[{"key":"A","text":"doubled"},{"key":"B","text":"tripled"},{"key":"C","text":"stayed the same"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Some employers encourage cycling by","options":[{"key":"A","text":"giving free bikes"},{"key":"B","text":"paying a bonus"},{"key":"C","text":"offering showers"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Critics are worried about","options":[{"key":"A","text":"cost"},{"key":"B","text":"safety"},{"key":"C","text":"pollution"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"What stops many people from cycling in winter?","options":[{"key":"A","text":"Darkness"},{"key":"B","text":"The weather"},{"key":"C","text":"Holidays"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"The future of cycling depends on","options":[{"key":"A","text":"technology"},{"key":"B","text":"investment"},{"key":"C","text":"fuel prices"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The writer’s view of cycling is","options":[{"key":"A","text":"negative"},{"key":"B","text":"uncertain"},{"key":"C","text":"positive"}]}]},{"id":"r4","index":4,"title":"Sleeping Cities: The Rise of Night Markets","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"Night markets have a long history in East Asia, but in recent years they have spread to Europe, Africa and Central Asia."},{"label":"B","text":"Most night markets open after sunset and stay open until midnight. They usually offer street food, crafts and live music."},{"label":"C","text":"Local councils often support these markets because they bring life to city centres that would otherwise be empty after office hours.","highlight":"bring life to city centres that would otherwise be empty"},{"label":"D","text":"However, some residents complain about noise and rubbish, and in a few cities markets have been moved to less central areas."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"Night markets first appeared in Europe."},{"id":"r-23","number":23,"kind":"tfng","prompt":"Most night markets close at around midnight."},{"id":"r-24","number":24,"kind":"tfng","prompt":"Night markets are the main source of income for local councils."},{"id":"r-25","number":25,"kind":"tfng","prompt":"Councils like night markets because they make city centres livelier."},{"id":"r-26","number":26,"kind":"tfng","prompt":"All residents are happy with night markets."}]},{"id":"r5","index":5,"title":"Why We Forget","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"In the 1880s, the psychologist Hermann Ebbinghaus showed that we forget most new information within a day unless we review it."},{"label":"B","text":"His “forgetting curve” also revealed a solution: reviewing material at increasing intervals, a technique now called spaced repetition."},{"label":"C","text":"Modern research adds that sleep plays a key role. During deep sleep, the brain moves memories into long-term storage."},{"label":"D","text":"Surprisingly, forgetting is not always bad. By removing unimportant details, the brain makes room for what really matters."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"When did Ebbinghaus do his research?","options":[{"key":"A","text":"In the 1780s"},{"key":"B","text":"In the 1880s"},{"key":"C","text":"In the 1980s"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"Without review, we forget most new information within","options":[{"key":"A","text":"an hour"},{"key":"B","text":"a day"},{"key":"C","text":"a week"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"Spaced repetition means reviewing material","options":[{"key":"A","text":"every day"},{"key":"B","text":"at increasing intervals"},{"key":"C","text":"once a month"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"During deep sleep, the brain","options":[{"key":"A","text":"forgets details"},{"key":"B","text":"stores memories long-term"},{"key":"C","text":"creates dreams"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"According to paragraph D, forgetting","options":[{"key":"A","text":"is always harmful"},{"key":"B","text":"can be useful"},{"key":"C","text":"is a sign of illness"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The word “reveal” is closest to","options":[{"key":"A","text":"hide"},{"key":"B","text":"show"},{"key":"C","text":"change"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"The “forgetting curve” was created by","options":[{"key":"A","text":"a doctor"},{"key":"B","text":"a psychologist"},{"key":"C","text":"a teacher"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"The text is mainly about","options":[{"key":"A","text":"memory and forgetting"},{"key":"B","text":"sleep disorders"},{"key":"C","text":"learning languages"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"A student who wants to remember more should","options":[{"key":"A","text":"study all night"},{"key":"B","text":"review often and sleep well"},{"key":"C","text":"avoid taking notes"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You recently bought a new laptop from an online shop called TechWorld. When it arrived, the screen was broken and the charger was missing.","prompt":"Write a message to your friend who recommended this shop. Tell them what happened and ask for their advice. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You recently bought a new laptop from an online shop called TechWorld. When it arrived, the screen was broken and the charger was missing.","prompt":"Write a letter to the customer service manager of TechWorld. Explain the problems, say how you feel and tell them what you want them to do. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Some people think that young people should be required to do unpaid voluntary work in their community. What are the advantages and disadvantages of this idea? Give reasons and examples. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you usually do in the mornings before work or study?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"Do you prefer spending time indoors or outdoors? Why?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Tell me about a place in your town that you like to visit.","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which kind of meal do you enjoy more? Why?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Do you think families spend less time together than in the past?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Talk about a time when you helped someone or your community. Say what you did, why you did it and how you felt afterwards.","image":"A group of volunteers planting trees in a city park","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Every student should learn to play a musical instrument at school. For: music improves concentration and creativity. Against: it takes time away from important subjects. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
