nswer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. What will the woman bring to the party?","question":1},{"voice":"man","text":"Mia's already made a cake for the party, and Jack is bringing the drinks."},{"voice":"woman","text":"OK, so I'll get some fruit on my way. Grapes and strawberries, maybe?"},{"voice":"narrator","text":"Question 2. Which bus should the man take?","question":2},{"voice":"man","text":"Excuse me, does the number twelve go to the hospital?"},{"voice":"woman","text":"It used to, but they changed the route last month. Take the twenty-one. It stops right outside the main entrance."},{"voice":"narrator","text":"Question 3. What is the weather going to be like tomorrow?","question":3},{"voice":"woman","text":"It's so windy today. I hope it's better for our picnic tomorrow."},{"voice":"man","text":"The forecast says the wind will stop, but it's going to rain all day. Let's have the picnic on Sunday instead."},{"voice":"narrator","text":"Question 4. Why is the man late?","question":4},{"voice":"woman","text":"You're forty minutes late! Did you oversleep again?"},{"voice":"man","text":"Not this time. I was at the station on time, but my train was cancelled and I had to wait for the next one."},{"voice":"narrator","text":"Question 5. What does the woman want to study?","question":5},{"voice":"man","text":"Your parents are both doctors. Are you going to study medicine too?"},{"voice":"woman","text":"Everyone expects that, or law, like my uncle. But I've always loved drawing buildings, so I've applied for architecture."},{"voice":"narrator","text":"Question 6. How long will the repair take?","question":6},{"voice":"man","text":"How long will it take to fix my washing machine?"},{"voice":"woman","text":"Usually about a week, because we have to order the part. But luckily we've got one in the warehouse, so it'll be ready in two days."},{"voice":"narrator","text":"Question 7. Where are the speakers?","question":7},{"voice":"woman","text":"Good evening. I have a reservation under the name Karimova. It's a double room for three nights."},{"voice":"man","text":"Welcome. Here's your key card. Breakfast is served from seven in the restaurant on the ground floor."},{"voice":"narrator","text":"Question 8. What time is the appointment now?","question":8},{"voice":"woman","text":"I have an appointment with Dr Lee at ten thirty, but I need to change it."},{"voice":"man","text":"Eleven o'clock is taken, I'm afraid. How about eleven thirty?"},{"voice":"woman","text":"That's fine. Eleven thirty, then."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call to a language school. Complete the notes. Write no more than two words."},{"voice":"woman","text":"Good afternoon, Greenway Language School."},{"voice":"man","text":"Hello. I'd like to join an English course. I did a beginner course last year, so I think I need the next level."},{"voice":"woman","text":"Then the intermediate course would be right for you. It's our most popular level.","question":9},{"voice":"man","text":"Great. When are the classes?"},{"voice":"woman","text":"There are two lessons a week, on Tuesday and Thursday. We used to have Monday classes, but not any more.","question":10},{"voice":"woman","text":"Classes start at six p.m. and finish at half past seven, so you can come after work.","question":11},{"voice":"man","text":"And how much does it cost?"},{"voice":"woman","text":"The full price is three hundred pounds, but if you register before the end of this month, you get sixty pounds off. So it would be two hundred and forty.","question":12},{"voice":"man","text":"How big are the groups?"},{"voice":"woman","text":"Never more than twelve students, so everyone gets a chance to speak.","question":13},{"voice":"woman","text":"And every Friday there's a free conversation club where you can practise with native speakers.","question":14},{"voice":"man","text":"That sounds good. Do I need to take a test first?"},{"voice":"woman","text":"Yes, a short placement test. You don't need to come in; you can take it online at home.","question":15},{"voice":"man","text":"And do I have to buy the books?"},{"voice":"woman","text":"No, the course books are included in the price.","question":16},{"voice":"man","text":"Perfect. Thank you."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about their hobbies. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"A friend kept telling me to try painting, but that's not why I started. I had a very stressful job, and I just needed something to help me relax in the evenings."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"People think getting up at six is the hardest part, or running in the rain. For me, it's keeping myself motivated. After a few weeks, it's so easy to find excuses."},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"man2","text":"My grandfather collected stamps and coins, but I've always preferred music. I've got more than five hundred vinyl records now, some of them from the nineteen sixties."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"woman2","text":"Everyone learns from videos these days, but I learned to cook from my grandmother. I spent every summer in her kitchen, watching her make plov and samsa."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"man3","text":"Chess is good for your memory, and it doesn't cost anything. But the main reason I love it is the club. I've made so many friends there."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"woman3","text":"I'm happy with my camera, and I don't want to sell my photos. But next month I'm going to enter a national photography competition. I'm really excited about it."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear a radio interview with a young app developer. Choose the correct answer."},{"voice":"woman","text":"Today I'm talking to Aziz, who created a very successful travel app at the age of nineteen. Aziz, where did the idea come from?"},{"voice":"man","text":"Not from school, and not from my parents. It came to me while I was travelling around Central Asia with a backpack. I kept wasting hours looking for cheap buses and shared taxis.","question":23},{"voice":"man","text":"So the app does exactly that: it helps people find cheap transport between cities. It's not for booking hotels or learning languages; it's all about getting from A to B.","question":24},{"voice":"woman","text":"What was the hardest part at the beginning?"},{"voice":"man","text":"I had a great team of friends, and the technical side was fine. The real problem was money. For the first year, I paid for everything from my savings.","question":25},{"voice":"woman","text":"And now?"},{"voice":"man","text":"We reached ten thousand users in the first month, and today we have about fifty thousand. We hope to reach a hundred thousand next year.","question":26},{"voice":"woman","text":"What would you say to young people who want to do the same?"},{"voice":"man","text":"Don't wait until you find investors or become an expert programmer. Start with a small idea that solves a real problem, and grow from there.","question":27},{"voice":"woman","text":"Aziz, thank you."},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear a ranger at Hillside National Park. Complete the notes. Write one word or a number."},{"voice":"man","text":"Welcome to Hillside National Park. The visitor centre opens at nine and closes at five, so please make sure you're back before then.","question":28},{"voice":"man","text":"There are three walking paths. The mountain path is quite difficult, and the forest path takes about four hours. The easiest one is the river path, which is flat and good for families.","question":29},{"voice":"man","text":"Please remember that you must not feed the birds. Human food makes them ill. Enjoy your visit!","question":30},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a talk about food waste. Choose the correct answer."},{"voice":"woman","text":"Good morning. Every year, around a third of all the food we produce is wasted. Many people blame farms or supermarkets, but in fact, most food waste happens in our own homes.","question":31},{"voice":"woman","text":"So what do we throw away? Fruit and meat are high on the list, but the most commonly wasted food is bread. Millions of slices go in the bin every day.","question":32},{"voice":"woman","text":"One reason is that many people misunderstand date labels. 'Best before' does not mean the food is dangerous after that date; it simply may not taste as fresh.","question":33},{"voice":"woman","text":"My main tip is simple: before you go shopping, make a shopping list and stick to it. You'll buy only what you need, and you'll save money too.","question":34},{"voice":"woman","text":"Governments and supermarkets can help, of course. But I believe real change has to start with individuals, with each of us, in our own kitchens. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

