values ('t13', 13, 'Mock Test #13', 8, 2026, true, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":172,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"Where does the woman want to meet?","options":[{"key":"A","text":"At the café"},{"key":"B","text":"At the station"},{"key":"C","text":"At the library"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"What time does the film start?","options":[{"key":"A","text":"6:15"},{"key":"B","text":"6:45"},{"key":"C","text":"7:15"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"How will the man travel to work tomorrow?","options":[{"key":"A","text":"By bus"},{"key":"B","text":"By bike"},{"key":"C","text":"By car"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"What does the girl need to buy?","options":[{"key":"A","text":"A notebook"},{"key":"B","text":"A calculator"},{"key":"C","text":"A dictionary"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"Why is the shop closed?","options":[{"key":"A","text":"It is a holiday"},{"key":"B","text":"It is being repaired"},{"key":"C","text":"The owner is ill"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"What does the man order?","options":[{"key":"A","text":"Soup"},{"key":"B","text":"A sandwich"},{"key":"C","text":"A salad"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"Where did the woman leave her keys?","options":[{"key":"A","text":"In the car"},{"key":"B","text":"On the desk"},{"key":"C","text":"In her bag"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"How much does the ticket cost?","options":[{"key":"A","text":"£12"},{"key":"B","text":"£15"},{"key":"C","text":"£20"}]}],"audio":"t13/l1.mp3","audioAt":{"1":8,"2":32,"3":56,"4":75,"5":93,"6":113,"7":130,"8":147}},{"id":"l2","index":2,"title":"Riverside Library — Membership","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":112,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Closes on weekdays at"},{"id":"l-10","number":10,"kind":"gap","prompt":"Student fee per year: £"},{"id":"l-11","number":11,"kind":"gap","prompt":"Bring a copy of your"},{"id":"l-12","number":12,"kind":"gap","prompt":"Maximum books at one time:"},{"id":"l-13","number":13,"kind":"gap","prompt":"Late return fine per day: £"},{"id":"l-14","number":14,"kind":"gap","prompt":"Quiet study room is on the"},{"id":"l-15","number":15,"kind":"gap","prompt":"Free workshop topic:"},{"id":"l-16","number":16,"kind":"gap","prompt":"Online catalogue password sent by"}],"audio":"t13/l2.mp3","audioAt":{"9":22,"10":35,"11":49,"12":60,"13":67,"14":77,"15":86,"16":96}},{"id":"l3","index":3,"instruction":"You will hear six people talking about their jobs. Choose the correct answer.","durationSec":101,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1 enjoys her job mainly because of","options":[{"key":"A","text":"the salary"},{"key":"B","text":"her colleagues"},{"key":"C","text":"the travel"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 finds it difficult to","options":[{"key":"A","text":"work at night"},{"key":"B","text":"meet deadlines"},{"key":"C","text":"speak in public"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 started his career as","options":[{"key":"A","text":"a teacher"},{"key":"B","text":"a journalist"},{"key":"C","text":"an engineer"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 would like to","options":[{"key":"A","text":"change jobs"},{"key":"B","text":"work abroad"},{"key":"C","text":"start a business"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 says her training was","options":[{"key":"A","text":"too short"},{"key":"B","text":"very practical"},{"key":"C","text":"expensive"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 thinks the best part of his job is","options":[{"key":"A","text":"helping people"},{"key":"B","text":"solving problems"},{"key":"C","text":"flexible hours"}]}],"audio":"t13/l3.mp3","audioAt":{"17":9,"18":23,"19":41,"20":55,"21":69,"22":84}},{"id":"l4","index":4,"instruction":"Listen to a radio interview. Choose the correct answer.","durationSec":104,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"The guest first became interested in gardening","options":[{"key":"A","text":"as a child"},{"key":"B","text":"at university"},{"key":"C","text":"after moving house"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"What is the main problem with city gardens?","options":[{"key":"A","text":"Lack of space"},{"key":"B","text":"Poor soil"},{"key":"C","text":"Air pollution"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"She recommends beginners to start with","options":[{"key":"A","text":"herbs"},{"key":"B","text":"tomatoes"},{"key":"C","text":"flowers"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"According to the guest, community gardens","options":[{"key":"A","text":"are expensive to run"},{"key":"B","text":"bring neighbours together"},{"key":"C","text":"need official permission"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"What will she talk about next week?","options":[{"key":"A","text":"Water saving"},{"key":"B","text":"Composting"},{"key":"C","text":"Garden tools"}]}],"audio":"t13/l4.mp3","audioAt":{"23":19,"24":36,"25":53,"26":71,"27":88}},{"id":"l5","index":5,"title":"City Museum — Guided Tour","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":45,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"Tour starts at the main"},{"id":"l-29","number":29,"kind":"gap","prompt":"Tour length in minutes:"},{"id":"l-30","number":30,"kind":"gap","prompt":"Photos are not allowed in the"}],"audio":"t13/l5.mp3","audioAt":{"28":9,"29":20,"30":27}},{"id":"l6","index":6,"instruction":"Listen to a lecture about sleep. Choose the correct answer.","durationSec":93,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"The lecturer says most adults need","options":[{"key":"A","text":"6 hours of sleep"},{"key":"B","text":"7–9 hours of sleep"},{"key":"C","text":"10 hours of sleep"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"Screens before bed mainly affect","options":[{"key":"A","text":"dreaming"},{"key":"B","text":"falling asleep"},{"key":"C","text":"waking up"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"Short naps are most useful","options":[{"key":"A","text":"in the morning"},{"key":"B","text":"after lunch"},{"key":"C","text":"in the evening"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"Teenagers tend to","options":[{"key":"A","text":"sleep earlier"},{"key":"B","text":"sleep later"},{"key":"C","text":"sleep less deeply"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"The lecture ends with advice about","options":[{"key":"A","text":"diet"},{"key":"B","text":"exercise"},{"key":"C","text":"routine"}]}],"audio":"t13/l6.mp3","audioAt":{"31":7,"32":28,"33":42,"34":56,"35":74}}],"reading":[{"id":"r1","index":1,"title":"Notice: Community Sports Centre","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"The Community Sports Centre will reopen on Monday after a two-month renovation. Members can now use the new swimming pool, which is open from 6 am until 10 pm every day."},{"label":"B","text":"Children under twelve must be accompanied by an adult. Lockers are free, but you need to bring your own lock. Towels can be rented at reception."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"The centre was closed for two"},{"id":"r-2","number":2,"kind":"gap","prompt":"The pool closes at 10 pm every"},{"id":"r-3","number":3,"kind":"gap","prompt":"Children under twelve need an"},{"id":"r-4","number":4,"kind":"gap","prompt":"Lockers cost"},{"id":"r-5","number":5,"kind":"gap","prompt":"You must bring your own"},{"id":"r-6","number":6,"kind":"gap","prompt":"Towels are available at"},{"id":"r-7","number":7,"kind":"gap","prompt":"The new facility is a swimming"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Hi Sam — the meeting has moved to Thursday. Same room, same time. Please bring the budget figures."},{"label":"B","text":"Parcel delivery: we tried to deliver your package today. It is now waiting at the post office on King Street."},{"label":"C","text":"Reminder: your dental check-up is tomorrow at 9:30. Please arrive ten minutes early."}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"What has changed about the meeting?","options":[{"key":"A","text":"The room"},{"key":"B","text":"The day"},{"key":"C","text":"The time"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"What should Sam bring?","options":[{"key":"A","text":"A report"},{"key":"B","text":"Budget figures"},{"key":"C","text":"A laptop"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"Where is the parcel now?","options":[{"key":"A","text":"At home"},{"key":"B","text":"At the post office"},{"key":"C","text":"With a neighbour"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"When is the dental appointment?","options":[{"key":"A","text":"Today"},{"key":"B","text":"Tomorrow"},{"key":"C","text":"Next week"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"The patient should arrive at","options":[{"key":"A","text":"9:10"},{"key":"B","text":"9:20"},{"key":"C","text":"9:30"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"Message B is from","options":[{"key":"A","text":"a shop"},{"key":"B","text":"a delivery service"},{"key":"C","text":"a friend"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message asks for preparation?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"Working From Home","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"Since 2020, millions of office workers have discovered the benefits of working from home. Many report saving over an hour a day on commuting."},{"label":"B","text":"However, managers worry that creativity suffers when teams rarely meet. Some companies now require staff to come in at least three days a week."},{"label":"C","text":"Researchers suggest that the best model depends on the task: focused work at home, collaboration in the office."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"What benefit do many workers mention?","options":[{"key":"A","text":"Higher pay"},{"key":"B","text":"Less commuting"},{"key":"C","text":"Better equipment"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"Managers are concerned about","options":[{"key":"A","text":"costs"},{"key":"B","text":"creativity"},{"key":"C","text":"security"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Some companies now ask staff to come in","options":[{"key":"A","text":"once a week"},{"key":"B","text":"three days a week"},{"key":"C","text":"every day"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Researchers believe the best model","options":[{"key":"A","text":"depends on the task"},{"key":"B","text":"is fully remote"},{"key":"C","text":"is fully in the office"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"Focused work is best done","options":[{"key":"A","text":"at home"},{"key":"B","text":"in the office"},{"key":"C","text":"in cafés"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"The writer’s attitude is","options":[{"key":"A","text":"critical"},{"key":"B","text":"balanced"},{"key":"C","text":"enthusiastic"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The best title for the article is","options":[{"key":"A","text":"The End of Offices"},{"key":"B","text":"Finding the Right Balance"},{"key":"C","text":"Why Commuting Matters"}]}]},{"id":"r4","index":4,"title":"The Quiet Revolution of Urban Beekeeping","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"Over the past decade, beehives have appeared on rooftops, balconies and school grounds in cities around the world."},{"label":"B","text":"Supporters argue that urban hives help pollinate parks and gardens, while also teaching residents about nature."},{"label":"C","text":"Early studies suggested rooftop hives would struggle, yet the opposite proved true. City bees often produce more honey than their rural counterparts, largely because parks offer a longer flowering season.","highlight":"City bees often produce more honey than their rural counterparts"},{"label":"D","text":"Not everyone is convinced. Ecologists warn that a sudden rise in managed hives may crowd out wild pollinators."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"Urban beehives can only be found on rooftops."},{"id":"r-23","number":23,"kind":"tfng","prompt":"Rooftop hives yield less honey than hives in the countryside."},{"id":"r-24","number":24,"kind":"tfng","prompt":"Parks have a longer flowering season than farmland."},{"id":"r-25","number":25,"kind":"tfng","prompt":"Most city residents support urban beekeeping."},{"id":"r-26","number":26,"kind":"tfng","prompt":"Some ecologists are worried about wild pollinators."}]},{"id":"r5","index":5,"title":"The Science of Habits","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"Psychologists estimate that around forty percent of our daily actions are habits rather than conscious decisions."},{"label":"B","text":"Every habit follows a loop: a cue, a routine and a reward. Changing the routine while keeping the cue and reward is the most reliable way to break a bad habit."},{"label":"C","text":"Contrary to popular belief, forming a new habit takes on average sixty-six days, not twenty-one."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"About what share of daily actions are habits?","options":[{"key":"A","text":"20%"},{"key":"B","text":"40%"},{"key":"C","text":"60%"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"A habit loop consists of","options":[{"key":"A","text":"two parts"},{"key":"B","text":"three parts"},{"key":"C","text":"four parts"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"To break a bad habit, you should change the","options":[{"key":"A","text":"cue"},{"key":"B","text":"routine"},{"key":"C","text":"reward"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"Forming a new habit takes on average","options":[{"key":"A","text":"21 days"},{"key":"B","text":"45 days"},{"key":"C","text":"66 days"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"The “21 days” idea is described as","options":[{"key":"A","text":"accurate"},{"key":"B","text":"a popular belief"},{"key":"C","text":"a new finding"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The text is mainly about","options":[{"key":"A","text":"how habits work"},{"key":"B","text":"healthy eating"},{"key":"C","text":"memory"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"The word “reliable” is closest to","options":[{"key":"A","text":"fast"},{"key":"B","text":"dependable"},{"key":"C","text":"difficult"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"Who made the estimate in paragraph A?","options":[{"key":"A","text":"Doctors"},{"key":"B","text":"Psychologists"},{"key":"C","text":"Teachers"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"The writer would most likely agree that","options":[{"key":"A","text":"habits cannot change"},{"key":"B","text":"change takes time"},{"key":"C","text":"rewards are useless"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You are a member of the City Sports Club. You have received this email from the club manager:\n\n\"Dear member, from next month the club will open two hours later in the morning and the swimming pool will close for six weeks for repairs. We apologise for any inconvenience.\"","prompt":"Write a letter to your friend who is also a member. Tell them about the changes and how you feel about them. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You are a member of the City Sports Club. You have received this email from the club manager:\n\n\"Dear member, from next month the club will open two hours later in the morning and the swimming pool will close for six weeks for repairs. We apologise for any inconvenience.\"","prompt":"Write a letter to the club manager. Say how the changes affect you and suggest what the club could do to help members. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Some people believe that cities should spend more money on public transport than on building new roads. To what extent do you agree or disagree? Give reasons and examples. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"Where do you live, and what do you like most about it?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How do you usually spend your weekends?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"What kind of music do you enjoy, and why?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: a busy open-air market · Picture B: a modern supermarket","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Where do you prefer to do your shopping? Why?","image":"Picture A: a busy open-air market · Picture B: a modern supermarket","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"How have shopping habits changed in your country in recent years?","image":"Picture A: a busy open-air market · Picture B: a modern supermarket","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe a skill you learned recently. Say how you learned it, why it was useful and how you felt about it.","image":"A young woman learning to play the guitar at home","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Online learning will replace traditional schools. For: lessons are flexible, cheaper and available anywhere. Against: students need teachers, friends and discipline. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
