insert into public.test_keys (test_id, keys, scripts)
values ('t14', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"C"},"l-4":{"answer":"B"},"l-5":{"answer":"A"},"l-6":{"answer":"C"},"l-7":{"answer":"A"},"l-8":{"answer":"B"},"l-9":{"answer":"animal shelter|shelter"},"l-10":{"answer":"18|eighteen"},"l-11":{"answer":"four|4","explanation":"Avval olti deyiladi, keyin minimum to'rt soat ekani aytiladi."},"l-12":{"answer":"Saturday|Saturdays"},"l-13":{"answer":"first Monday"},"l-14":{"answer":"uniform"},"l-15":{"answer":"Karimova"},"l-16":{"answer":"website"},"l-17":{"answer":"A"},"l-18":{"answer":"B"},"l-19":{"answer":"C"},"l-20":{"answer":"C"},"l-21":{"answer":"C"},"l-22":{"answer":"A"},"l-23":{"answer":"A"},"l-24":{"answer":"B"},"l-25":{"answer":"B"},"l-26":{"answer":"C"},"l-27":{"answer":"A"},"l-28":{"answer":"hall"},"l-29":{"answer":"30|thirty"},"l-30":{"answer":"registration"},"l-31":{"answer":"B"},"l-32":{"answer":"B"},"l-33":{"answer":"B"},"l-34":{"answer":"A"},"l-35":{"answer":"B"},"r-1":{"answer":"period"},"r-2":{"answer":"card"},"r-3":{"answer":"rooms"},"r-4":{"answer":"lids"},"r-5":{"answer":"midnight"},"r-6":{"answer":"online"},"r-7":{"answer":"hours"},"r-8":{"answer":"B"},"r-9":{"answer":"B"},"r-10":{"answer":"B"},"r-11":{"answer":"B"},"r-12":{"answer":"B"},"r-13":{"answer":"B"},"r-14":{"answer":"B"},"r-15":{"answer":"B"},"r-16":{"answer":"B"},"r-17":{"answer":"A"},"r-18":{"answer":"B"},"r-19":{"answer":"B"},"r-20":{"answer":"B"},"r-21":{"answer":"B"},"r-22":{"answer":"True"},"r-23":{"answer":"False"},"r-24":{"answer":"True","explanation":"C paragrafi: \"changed research completely\"."},"r-25":{"answer":"Not given"},"r-26":{"answer":"False"},"r-27":{"answer":"B"},"r-28":{"answer":"B"},"r-29":{"answer":"B"},"r-30":{"answer":"B"},"r-31":{"answer":"B"},"r-32":{"answer":"A"},"r-33":{"answer":"B"},"r-34":{"answer":"A"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. What is the woman looking for?","question":1},{"voice":"man","text":"What are you looking for? Your phone is on the table, and your passport is in your bag."},{"voice":"woman","text":"I know. It's my glasses. I can't read anything without them."},{"voice":"narrator","text":"Question 2. How will the man pay?","question":2},{"voice":"woman","text":"That will be ninety thousand sum. Cash or card?"},{"voice":"man","text":"I'd prefer to pay by bank transfer, but I don't have my phone. So card, please."},{"voice":"narrator","text":"Question 3. What does the boy want to be?","question":3},{"voice":"woman","text":"Do you still want to be a pilot, Sardor?"},{"voice":"man2","text":"Not any more. Dad wants me to be a doctor, but I love computers. I'm going to be a programmer."},{"voice":"narrator","text":"Question 4. Where did the woman go on Sunday?","question":4},{"voice":"man","text":"Did you go to your cousin’s wedding on Sunday?"},{"voice":"woman","text":"That was on Saturday. On Sunday we drove to the mountains. It was beautiful. We're going to the theatre next week."},{"voice":"narrator","text":"Question 5. What is the problem with the flat?","question":5},{"voice":"woman","text":"The flat is lovely, and the neighbours are quiet. The windows are new too. But the heating doesn't work, and it's freezing at night."},{"voice":"narrator","text":"Question 6. How long has the man been waiting?","question":6},{"voice":"woman","text":"Sorry I'm late! Have you been waiting long? Ten minutes?"},{"voice":"man","text":"More like half an hour. I got here at ten, and it's half past now."},{"voice":"narrator","text":"Question 7. Which course will the woman take?","question":7},{"voice":"man","text":"Are you doing the painting course again this year?"},{"voice":"woman","text":"No, the pottery course was full, so I've signed up for photography. I've just bought a new camera."},{"voice":"narrator","text":"Question 8. When will the parcel arrive?","question":8},{"voice":"man","text":"Will my parcel arrive tomorrow morning?"},{"voice":"woman","text":"The morning deliveries are full, but the driver will bring it tomorrow afternoon, between two and five."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call to a volunteering organisation. Complete the notes. Write no more than two words."},{"voice":"man","text":"City Volunteers, good morning."},{"voice":"woman","text":"Hello. I'd like to volunteer. I saw that you need people to help at the animal shelter.","question":9},{"voice":"man","text":"That's right. Can I ask how old you are? Volunteers must be at least eighteen.","question":10},{"voice":"woman","text":"I'm twenty-two. How much time would I need to give?"},{"voice":"man","text":"Most of our volunteers do about six hours a week, but the minimum is four hours.","question":11},{"voice":"man","text":"And volunteers usually work on Saturday, because that is when most visitors come.","question":12},{"voice":"man","text":"Before you start, there is a training session on the first Monday of every month.","question":13},{"voice":"woman","text":"Do I need special clothes?"},{"voice":"man","text":"No, you get a free uniform, a green T-shirt and a jacket.","question":14},{"voice":"woman","text":"Who should I contact?"},{"voice":"man","text":"Mrs Karimova. That's K-A-R-I-M-O-V-A. She organises all the volunteers.","question":15},{"voice":"man","text":"You can download the application form from our website. We don't send paper forms any more.","question":16},{"voice":"woman","text":"Thank you so much."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about moving to a new city. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"My husband's job didn't change, and I actually preferred the climate at home. But I got a place at a great university here, so we moved for my studies."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"Finding a flat was easy, and I already spoke the language. The difficult part was making friends. For months I only knew people from work."},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"man2","text":"I call my family every day, and the food here is great. What I really miss is the sea. I grew up next to it, and now I'm a thousand kilometres away."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"woman2","text":"It's definitely not cheaper, and I'm not sure it's safer. But it's much more exciting. There's always a concert or an exhibition to go to."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"man3","text":"My neighbours were polite but busy, and I didn't know anyone at work yet. Luckily, I found an online group for newcomers. They helped me with everything."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"woman3","text":"People ask if I'll move back home one day, or somewhere else. Honestly, no. I've found my place. I'm staying here for the rest of my life."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear an interview with a mountain guide. Choose the correct answer."},{"voice":"woman","text":"My guest is Bakhtiyor, who has been a mountain guide for twenty years. How did you start climbing?"},{"voice":"man","text":"I joined a sports club later, and I did some climbing in the army. But I really started with my father. He took me to the mountains when I was seven.","question":23},{"voice":"man","text":"People fear the cold or wild animals, but the most dangerous thing is how suddenly the weather can change. A sunny morning can become a storm in an hour.","question":24},{"voice":"woman","text":"What mistakes do beginners make?"},{"voice":"man","text":"They often carry too much, and some forget to drink. But the most common mistake is walking too fast at the start. They're exhausted after two hours.","question":25},{"voice":"man","text":"Summer is busy, and spring can be wet. My favourite season is autumn: the air is clear, and the colours are amazing.","question":26},{"voice":"woman","text":"Should more tourists come to the mountains?"},{"voice":"man","text":"Tourism is good for local villages, but it must be limited. Too many visitors damage the paths and leave rubbish. We need to protect these places.","question":27},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear an announcement at a university open day. Complete the notes. Write one word or a number."},{"voice":"woman","text":"Welcome to our Open Day! The welcome talk by the rector starts at ten in the main hall, on the first floor.","question":28},{"voice":"woman","text":"After that, you can join a campus tour. Tours start every thirty minutes from the front door.","question":29},{"voice":"woman","text":"And don't forget: you can get a free lunch ticket at registration, when you collect your badge.","question":30},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a lecture about climate and cities. Choose the correct answer."},{"voice":"man","text":"Good morning. Have you noticed that cities are hotter than the countryside? Traffic and factories add some heat, but the main reason is concrete and asphalt. They absorb heat during the day and release it at night.","question":31},{"voice":"man","text":"The difference can be surprising. In summer, a city centre can be up to five degrees hotter than the villages around it.","question":32},{"voice":"man","text":"What can we do? One solution is green roofs. They don't just look nice; plants on the roof help cool the buildings below.","question":33},{"voice":"man","text":"Painting roofs white and building fountains also help. But the cheapest and most effective solution is simply planting more trees along the streets.","question":34},{"voice":"man","text":"Summers will get hotter. Cities don't need to stop growing, but they must plan for the heat now, not in twenty years. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t15', 15, 'Mock Test #15', 9, 2026, true, false, true, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":141,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"What will the weather be like at the weekend?","options":[{"key":"A","text":"Cold and sunny"},{"key":"B","text":"Warm and rainy"},{"key":"C","text":"Snowy"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"Where does the man work now?","options":[{"key":"A","text":"In a bank"},{"key":"B","text":"In a school"},{"key":"C","text":"In a hospital"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"What time does the train leave?","options":[{"key":"A","text":"8:05"},{"key":"B","text":"8:15"},{"key":"C","text":"8:50"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"What does the woman want to drink?","options":[{"key":"A","text":"Water"},{"key":"B","text":"Tea"},{"key":"C","text":"Lemonade"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"Why is the man selling his car?","options":[{"key":"A","text":"It is too old"},{"key":"B","text":"He is moving abroad"},{"key":"C","text":"He needs money"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"How did the woman hurt her arm?","options":[{"key":"A","text":"Playing tennis"},{"key":"B","text":"Falling off a bike"},{"key":"C","text":"Carrying boxes"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"What will they cook tonight?","options":[{"key":"A","text":"Plov"},{"key":"B","text":"Pasta"},{"key":"C","text":"Soup"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"Which room is the exam in?","options":[{"key":"A","text":"Room 104"},{"key":"B","text":"Room 140"},{"key":"C","text":"Room 214"}]}],"audio":"t15/l1.mp3","audioAt":{"1":8,"2":26,"3":43,"4":57,"5":72,"6":90,"7":107,"8":124}},{"id":"l2","index":2,"title":"Bright Future Scholarship — Information","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":71,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Scholarship is for students of"},{"id":"l-10","number":10,"kind":"gap","prompt":"Application deadline: 30"},{"id":"l-11","number":11,"kind":"gap","prompt":"Amount per year: $"},{"id":"l-12","number":12,"kind":"gap","prompt":"Applicants need two"},{"id":"l-13","number":13,"kind":"gap","prompt":"Essay length (words):"},{"id":"l-14","number":14,"kind":"gap","prompt":"Interviews are held in"},{"id":"l-15","number":15,"kind":"gap","prompt":"Winners must keep a high"},{"id":"l-16","number":16,"kind":"gap","prompt":"Questions can be sent by"}],"audio":"t15/l2.mp3","audioAt":{"9":12,"10":21,"11":27,"12":37,"13":42,"14":46,"15":50,"16":59}},{"id":"l3","index":3,"instruction":"You will hear six people talking about their first job. Choose the correct answer.","durationSec":82,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1’s first job was in","options":[{"key":"A","text":"a café"},{"key":"B","text":"a bookshop"},{"key":"C","text":"a hotel"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 remembers that the job was","options":[{"key":"A","text":"boring"},{"key":"B","text":"well paid"},{"key":"C","text":"tiring"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 learned most about","options":[{"key":"A","text":"teamwork"},{"key":"B","text":"money"},{"key":"C","text":"customers"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 left the job because","options":[{"key":"A","text":"she went to university"},{"key":"B","text":"the pay was low"},{"key":"C","text":"the boss was rude"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 got the job through","options":[{"key":"A","text":"an advert"},{"key":"B","text":"his uncle"},{"key":"C","text":"his school"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 says the job helped her","options":[{"key":"A","text":"choose a career"},{"key":"B","text":"buy a car"},{"key":"C","text":"travel"}]}],"audio":"t15/l3.mp3","audioAt":{"17":9,"18":21,"19":34,"20":46,"21":56,"22":66}},{"id":"l4","index":4,"instruction":"Listen to an interview with a sports coach. Choose the correct answer.","durationSec":71,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"The coach started working with children","options":[{"key":"A","text":"ten years ago"},{"key":"B","text":"after an injury"},{"key":"C","text":"at university"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"He believes children should first learn to","options":[{"key":"A","text":"win"},{"key":"B","text":"enjoy sport"},{"key":"C","text":"train hard"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"The biggest problem for young athletes is","options":[{"key":"A","text":"pressure from parents"},{"key":"B","text":"lack of equipment"},{"key":"C","text":"poor coaching"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"He recommends children try","options":[{"key":"A","text":"one sport only"},{"key":"B","text":"several sports"},{"key":"C","text":"team sports only"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"His team’s next competition is in","options":[{"key":"A","text":"Tashkent"},{"key":"B","text":"Almaty"},{"key":"C","text":"Istanbul"}]}],"audio":"t15/l4.mp3","audioAt":{"23":13,"24":22,"25":35,"26":45,"27":56}},{"id":"l5","index":5,"title":"Art Workshop for Beginners","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":34,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"Workshop room is on floor"},{"id":"l-29","number":29,"kind":"gap","prompt":"Participants should bring an"},{"id":"l-30","number":30,"kind":"gap","prompt":"The final work will be shown in an"}],"audio":"t15/l5.mp3","audioAt":{"28":9,"29":18,"30":24}},{"id":"l6","index":6,"instruction":"Listen to a lecture about the history of coffee. Choose the correct answer.","durationSec":69,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"Coffee was first discovered in","options":[{"key":"A","text":"Brazil"},{"key":"B","text":"Ethiopia"},{"key":"C","text":"Turkey"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"According to the legend, the discovery was made by","options":[{"key":"A","text":"a farmer"},{"key":"B","text":"a goat herder"},{"key":"C","text":"a king"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"The first coffee houses appeared in","options":[{"key":"A","text":"Europe"},{"key":"B","text":"the Middle East"},{"key":"C","text":"America"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"Coffee houses in Europe were called “penny universities” because people","options":[{"key":"A","text":"studied there"},{"key":"B","text":"discussed ideas"},{"key":"C","text":"paid teachers"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"Today the largest producer of coffee is","options":[{"key":"A","text":"Brazil"},{"key":"B","text":"Vietnam"},{"key":"C","text":"Colombia"}]}],"audio":"t15/l6.mp3","audioAt":{"31":8,"32":19,"33":29,"34":41,"35":51}}],"reading":[{"id":"r1","index":1,"title":"Notice: Bike Sharing Scheme","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"The city’s new bike sharing scheme starts on 1 May. More than two hundred bikes will be available at thirty stations across the centre."},{"label":"B","text":"To use a bike, download the CityBike app and register with your phone number. The first thirty minutes of every ride are free."},{"label":"C","text":"Bikes must be returned to a station, not left on the street. Riders under sixteen are not allowed to use the service."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"The scheme begins in"},{"id":"r-2","number":2,"kind":"gap","prompt":"Bikes can be found at thirty"},{"id":"r-3","number":3,"kind":"gap","prompt":"Users must download an"},{"id":"r-4","number":4,"kind":"gap","prompt":"To register, you need your phone"},{"id":"r-5","number":5,"kind":"gap","prompt":"The first half an hour is"},{"id":"r-6","number":6,"kind":"gap","prompt":"Bikes must not be left on the"},{"id":"r-7","number":7,"kind":"gap","prompt":"The minimum age is"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Jasur, the plumber is coming at 10 tomorrow to fix the kitchen tap. Can you be at home? I have an early meeting."},{"label":"B","text":"Museum news: from Monday, entry is free for students every Wednesday afternoon. Just show your student card at the desk."},{"label":"C","text":"Hi everyone! Our reunion dinner is moved from the 12th to the 19th because the restaurant is closed. Hope you can still come!"}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"What will the plumber fix?","options":[{"key":"A","text":"The shower"},{"key":"B","text":"The kitchen tap"},{"key":"C","text":"The heating"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"Why can’t the writer be at home?","options":[{"key":"A","text":"She is travelling"},{"key":"B","text":"She has a meeting"},{"key":"C","text":"She is ill"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"When is museum entry free for students?","options":[{"key":"A","text":"Every Monday"},{"key":"B","text":"Wednesday afternoons"},{"key":"C","text":"At weekends"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"What must students show?","options":[{"key":"A","text":"A ticket"},{"key":"B","text":"A student card"},{"key":"C","text":"A passport"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"What is the new date of the dinner?","options":[{"key":"A","text":"The 12th"},{"key":"B","text":"The 19th"},{"key":"C","text":"The 21st"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"Why was the dinner moved?","options":[{"key":"A","text":"The restaurant is closed"},{"key":"B","text":"People are busy"},{"key":"C","text":"It is a holiday"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message gives information to the public?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"The Rise of Audiobooks","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"Audiobooks are more popular than ever. In the last five years, the number of people listening to them has almost tripled."},{"label":"B","text":"Many listeners say audiobooks let them “read” while doing other things, such as driving, cooking or exercising."},{"label":"C","text":"Some teachers worry that listening is not the same as reading. However, studies show that people understand stories equally well in both forms."},{"label":"D","text":"Publishers now hire famous actors to record books, turning a simple reading into a real performance."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"The number of audiobook listeners has","options":[{"key":"A","text":"doubled"},{"key":"B","text":"almost tripled"},{"key":"C","text":"fallen"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"People like audiobooks because they can","options":[{"key":"A","text":"learn faster"},{"key":"B","text":"do other things at the same time"},{"key":"C","text":"save money"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Some teachers are concerned that","options":[{"key":"A","text":"audiobooks are expensive"},{"key":"B","text":"listening differs from reading"},{"key":"C","text":"children stop studying"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Studies show that understanding of stories is","options":[{"key":"A","text":"better with reading"},{"key":"B","text":"better with listening"},{"key":"C","text":"the same"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"Publishers now use","options":[{"key":"A","text":"computer voices"},{"key":"B","text":"famous actors"},{"key":"C","text":"authors only"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"The word “performance” refers to","options":[{"key":"A","text":"a show"},{"key":"B","text":"a test"},{"key":"C","text":"a sale"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The writer’s attitude to audiobooks is","options":[{"key":"A","text":"negative"},{"key":"B","text":"positive"},{"key":"C","text":"worried"}]}]},{"id":"r4","index":4,"title":"Tashkent Metro: An Underground Museum","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"Opened in 1977, the Tashkent Metro was the first underground railway in Central Asia."},{"label":"B","text":"Each station has its own design, with marble walls, chandeliers and mosaics that tell stories about the history and culture of Uzbekistan."},{"label":"C","text":"For many years, taking photographs in the metro was forbidden. The ban was lifted in 2018, and the stations quickly became popular on social media.","highlight":"The ban was lifted in 2018"},{"label":"D","text":"Today the network continues to grow, with new lines connecting the city centre to its outer districts."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"The Tashkent Metro opened in the 1970s."},{"id":"r-23","number":23,"kind":"tfng","prompt":"All metro stations look the same."},{"id":"r-24","number":24,"kind":"tfng","prompt":"Photography in the metro is still banned."},{"id":"r-25","number":25,"kind":"tfng","prompt":"The metro carries more than a million passengers a day."},{"id":"r-26","number":26,"kind":"tfng","prompt":"New metro lines are being built."}]},{"id":"r5","index":5,"title":"The Truth About Multitasking","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"Many people are proud of their ability to multitask, answering messages while working or studying."},{"label":"B","text":"Research shows, however, that the brain cannot focus on two demanding tasks at once. Instead, it switches quickly between them."},{"label":"C","text":"Each switch costs time and energy. People who multitask make up to fifty percent more mistakes and take longer to finish."},{"label":"D","text":"Experts recommend “single-tasking”: working on one task for a set period, for example twenty-five minutes, before taking a short break."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"Many people believe multitasking is","options":[{"key":"A","text":"impossible"},{"key":"B","text":"a useful skill"},{"key":"C","text":"dangerous"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"According to research, the brain","options":[{"key":"A","text":"does two tasks at once"},{"key":"B","text":"switches between tasks"},{"key":"C","text":"stops working"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"Switching between tasks costs","options":[{"key":"A","text":"money"},{"key":"B","text":"time and energy"},{"key":"C","text":"nothing"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"People who multitask make up to","options":[{"key":"A","text":"15% more mistakes"},{"key":"B","text":"25% more mistakes"},{"key":"C","text":"50% more mistakes"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"Experts suggest working on one task for","options":[{"key":"A","text":"ten minutes"},{"key":"B","text":"twenty-five minutes"},{"key":"C","text":"two hours"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The word “demanding” is closest to","options":[{"key":"A","text":"easy"},{"key":"B","text":"difficult"},{"key":"C","text":"boring"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"Paragraph D gives","options":[{"key":"A","text":"a warning"},{"key":"B","text":"a recommendation"},{"key":"C","text":"a history"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"The text mainly shows that multitasking","options":[{"key":"A","text":"is effective"},{"key":"B","text":"is less effective than people think"},{"key":"C","text":"is a new trend"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"A student preparing for an exam should","options":[{"key":"A","text":"answer messages while studying"},{"key":"B","text":"focus on one task at a time"},{"key":"C","text":"study without breaks"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You live in a block of flats. You have received this notice from the building management:\n\n\"From next month, the children’s playground behind the building will be replaced by a car park for residents.\"","prompt":"Write a message to a neighbour who has young children. Tell them about the notice and how you feel about it. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You live in a block of flats. You have received this notice from the building management:\n\n\"From next month, the children’s playground behind the building will be replaced by a car park for residents.\"","prompt":"Write a letter to the building management. Explain your opinion about the plan and suggest an alternative. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Some people believe that students should be allowed to choose all the subjects they study at school. Others think that schools should decide. Discuss both views and give your own opinion. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What is your favourite season, and why?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How often do you use the internet, and what for?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Tell me about your best friend.","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which way of shopping do you prefer? Why?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"What are the risks of shopping online?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe a teacher who has had a strong influence on you. Say who they were, what they taught you and why they were special.","image":"A woman teaching a small group of adults in a community centre","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Everyone should do sport every day. For: sport keeps people healthy and reduces stress. Against: people have different interests and not enough time. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
