values ('t15', $json${"l-1":{"answer":"A"},"l-2":{"answer":"C"},"l-3":{"answer":"B"},"l-4":{"answer":"C"},"l-5":{"answer":"B"},"l-6":{"answer":"B"},"l-7":{"answer":"B"},"l-8":{"answer":"C"},"l-9":{"answer":"engineering"},"l-10":{"answer":"November"},"l-11":{"answer":"3000|3,000","explanation":"Avval 5000 deyiladi, bu umumiy byudjet — har bir talabaga 3000."},"l-12":{"answer":"references"},"l-13":{"answer":"500|five hundred"},"l-14":{"answer":"January"},"l-15":{"answer":"average|grade average"},"l-16":{"answer":"email"},"l-17":{"answer":"B"},"l-18":{"answer":"C"},"l-19":{"answer":"A"},"l-20":{"answer":"A"},"l-21":{"answer":"B"},"l-22":{"answer":"A"},"l-23":{"answer":"B"},"l-24":{"answer":"B"},"l-25":{"answer":"A"},"l-26":{"answer":"B"},"l-27":{"answer":"B"},"l-28":{"answer":"3|three"},"l-29":{"answer":"apron"},"l-30":{"answer":"exhibition"},"l-31":{"answer":"B"},"l-32":{"answer":"B"},"l-33":{"answer":"B"},"l-34":{"answer":"B"},"l-35":{"answer":"A"},"r-1":{"answer":"May"},"r-2":{"answer":"stations"},"r-3":{"answer":"app"},"r-4":{"answer":"number"},"r-5":{"answer":"free"},"r-6":{"answer":"street"},"r-7":{"answer":"sixteen|16"},"r-8":{"answer":"B"},"r-9":{"answer":"B"},"r-10":{"answer":"B"},"r-11":{"answer":"B"},"r-12":{"answer":"B"},"r-13":{"answer":"A"},"r-14":{"answer":"B"},"r-15":{"answer":"B"},"r-16":{"answer":"B"},"r-17":{"answer":"B"},"r-18":{"answer":"C"},"r-19":{"answer":"B"},"r-20":{"answer":"A"},"r-21":{"answer":"B"},"r-22":{"answer":"True"},"r-23":{"answer":"False"},"r-24":{"answer":"False","explanation":"C paragrafi: taqiq 2018-yilda bekor qilingan."},"r-25":{"answer":"Not given"},"r-26":{"answer":"True"},"r-27":{"answer":"B"},"r-28":{"answer":"B"},"r-29":{"answer":"B"},"r-30":{"answer":"C"},"r-31":{"answer":"B"},"r-32":{"answer":"B"},"r-33":{"answer":"B"},"r-34":{"answer":"B"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. What will the weather be like at the weekend?","question":1},{"voice":"man","text":"It's been raining all week. Is it going to be warm at the weekend?"},{"voice":"woman","text":"The rain will stop, but it won't be warm. The forecast says cold and sunny, so take a jacket."},{"voice":"narrator","text":"Question 2. Where does the man work now?","question":2},{"voice":"woman","text":"Are you still teaching at the school?"},{"voice":"man","text":"No, I left last year. I worked in a bank for a few months, and now I'm a nurse at the city hospital."},{"voice":"narrator","text":"Question 3. What time does the train leave?","question":3},{"voice":"woman","text":"Does the train leave at eight fifty?"},{"voice":"man","text":"No, it's eight fifteen. The eight oh five is the bus. We'd better hurry."},{"voice":"narrator","text":"Question 4. What does the woman want to drink?","question":4},{"voice":"man","text":"Would you like some tea? Or just water?"},{"voice":"woman","text":"It's so hot today. Have you got any lemonade? That would be perfect."},{"voice":"narrator","text":"Question 5. Why is the man selling his car?","question":5},{"voice":"woman","text":"Why are you selling your car? It's almost new, and I know you don't need the money."},{"voice":"man","text":"I'm moving abroad next month for work, and I can't take it with me."},{"voice":"narrator","text":"Question 6. How did the woman hurt her arm?","question":6},{"voice":"man","text":"What happened to your arm? Was it tennis again?"},{"voice":"woman","text":"Not this time. I fell off my bike on the way to work. A car stopped suddenly in front of me."},{"voice":"narrator","text":"Question 7. What will they cook tonight?","question":7},{"voice":"woman","text":"Shall we make plov tonight?"},{"voice":"man","text":"We had plov yesterday, and soup takes too long. Let's make pasta. It's quick and easy."},{"voice":"narrator","text":"Question 8. Which room is the exam in?","question":8},{"voice":"man","text":"Is the exam in room one-oh-four?"},{"voice":"woman","text":"That was last year. This year it's in room two-fourteen, on the second floor."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call about a scholarship. Complete the notes. Write no more than two words."},{"voice":"woman","text":"Bright Future Foundation, how can I help you?"},{"voice":"man","text":"Hello. I'm interested in your scholarship. Is it for all students?","question":9},{"voice":"woman","text":"No, this year it's only for students of engineering."},{"voice":"man","text":"When is the deadline?","question":10},{"voice":"woman","text":"Applications must arrive by the thirtieth of November."},{"voice":"woman","text":"The programme has a budget of five thousand dollars in total, but each student receives three thousand dollars per year.","question":11},{"voice":"man","text":"What do I need to send?"},{"voice":"woman","text":"Your exam results and two references, for example from your teachers.","question":12},{"voice":"woman","text":"You also need to write an essay of five hundred words about your goals.","question":13},{"voice":"woman","text":"The best candidates will be invited to an interview in January.","question":14},{"voice":"woman","text":"And remember, winners must keep a high average during their studies, or they lose the scholarship.","question":15},{"voice":"man","text":"If I have more questions?"},{"voice":"woman","text":"Please send them by email. The phone line is only open on Mondays.","question":16},{"voice":"man","text":"Thank you very much."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about their first job. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"Most of my friends worked in cafés or hotels, but my first job was in a small bookshop. I read so many books during quiet afternoons."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"It wasn't boring at all, and the pay was OK. But it was so tiring. I delivered newspapers at five in the morning before school."},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"man2","text":"I earned my first money and met lots of customers, but the biggest lesson was teamwork. In a busy kitchen, you can't do anything alone."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"woman2","text":"My boss was kind, and the pay was fine. I only left because I got a place at university in another city."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"man3","text":"I didn't answer an advert, and my school didn't help. My uncle owned a garage, and he gave me a job for the summer."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"woman3","text":"I worked as a receptionist at a dental clinic. I didn't earn much, but watching the dentists helped me choose my career. I'm a dentist now."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear an interview with a sports coach. Choose the correct answer."},{"voice":"woman","text":"My guest is Rustam, who coaches young swimmers. How did you start working with children?"},{"voice":"man","text":"I was a professional swimmer until I had a serious shoulder injury. After that, I couldn't compete, so I started coaching children.","question":23},{"voice":"man","text":"Many coaches focus on winning and hard training. I believe children should first learn to enjoy sport. Winning comes later.","question":24},{"voice":"woman","text":"What problems do young athletes face?"},{"voice":"man","text":"Equipment and coaching are much better now. The biggest problem is pressure from parents who expect medals too early.","question":25},{"voice":"man","text":"I always recommend trying several sports before choosing one. It builds a stronger, more balanced body.","question":26},{"voice":"woman","text":"What's next for your team?"},{"voice":"man","text":"We competed in Tashkent last month. Our next competition is in Almaty in March, and next year maybe Istanbul.","question":27},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear an introduction to an art workshop. Complete the notes. Write one word or a number."},{"voice":"woman","text":"Welcome to the beginners' art workshop. All our sessions take place in the studio on floor three. The lift is next to the entrance.","question":28},{"voice":"woman","text":"We provide paints and brushes, but please bring an apron, because painting can get messy.","question":29},{"voice":"woman","text":"At the end of the course, your final work will be shown in an exhibition for your family and friends.","question":30},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a lecture about the history of coffee. Choose the correct answer."},{"voice":"man","text":"Good afternoon. Today, coffee is grown in Brazil, Vietnam and many other countries, but it was first discovered in Ethiopia, more than a thousand years ago.","question":31},{"voice":"man","text":"According to a famous legend, a goat herder noticed that his goats became very energetic after eating red berries from a certain bush.","question":32},{"voice":"man","text":"From Africa, coffee travelled to the Middle East, where the first coffee houses appeared in the fifteenth century. Europe followed much later.","question":33},{"voice":"man","text":"In England, coffee houses were called 'penny universities'. For the price of a cup, people could listen to and discuss the latest ideas.","question":34},{"voice":"man","text":"And today? Vietnam and Colombia are major producers, but Brazil is still the largest producer of coffee in the world. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;
